  window.SERVICE_CUSTOM_VIEWS = {
    "quality-review-copyediting": "<div class=\"quality-review-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.quality-review-copyediting.prereq\">\n      Prerequisite: Omni Copyediting. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-copyediting.p1\">\n      Our Quality Review - Copyediting service provides a final check to make sure your revised manuscript is sound before it goes into production—for a fraction of the price of your original edit.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-copyediting.p2\">\n      After you review and revise your edited manuscript, you may want an editor to check your work to ensure that you've done it correctly and haven't created new errors in the process.\n    </p>\n    <blockquote class=\"editorial-testimonial-quote\" style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173, 125, 66, 0.05); border-radius: 0 8px 8px 0; font-style: italic; color: #333;\">\n      <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.quality-review-copyediting.quote\">\n        \"I am really impressed by [the editor's] incredible attention to detail, and I am just so grateful there are people like her who can subject my writing to such close critical analysis.\"\n      </p>\n      <footer style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\" class=\"editable-field\" data-block-key=\"service.quality-review-copyediting.author\">\n        — Michelle Dixon, author of <em>The Disappearance of Lilya Bekirova</em>\n      </footer>\n    </blockquote>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-copyediting.p3\">\n      With the Quality Review, an editor will not only review the work you've done on the manuscript in response to the editing, but ensure that you've adequately addressed all of the queries and comments.\n    </p>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.quality-review-copyediting.note\">\n      *There is a 5,000-word minimum charge for all editing services.\n    </p>\n  </div>\n</div>",
    "quality-review-line-editing": "<div class=\"quality-review-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.quality-review-line-editing.prereq\">\n      Prerequisite: Omni Line Editing. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-line-editing.p1\">\n      Our Quality Review - Line Editing service provides a final check to make sure your revised manuscript is sound before it goes into production—for a fraction of the price of your original edit.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-line-editing.p2\">\n      After you review and revise your edited manuscript, you may want an editor to check your work to ensure that you've done it correctly and haven't created new errors in the process.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-line-editing.p3\">\n      With the Quality Review, an editor will not only review the work you've done on the manuscript in response to the editing, but ensure that you've adequately addressed all of the queries and comments.\n    </p>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.quality-review-line-editing.note\">\n      *There is a 5,000-word minimum charge for all editing services.\n    </p>\n  </div>\n</div>",
    "quality-review-content-editing": "<div class=\"quality-review-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.quality-review-content-editing.prereq\">\n      Prerequisite: Omni Content Editing. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing.p1\">\n      Our Quality Review - Content Editing service provides a final check to make sure your revised manuscript is sound before it goes into production—for a fraction of the price of your original edit.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing.p2\">\n      After you review and revise your edited manuscript, you may want an editor to check your work to ensure that you've done it correctly and haven't created new errors in the process.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing.p3\">\n      Content Editing, by its very nature, involves extensive revisions to your manuscript — for example, restructuring sentences and adding material. With the Quality Review, an editor will not only review the work you've done on the manuscript in response to the editing, but ensure that you've adequately addressed all of the queries and comments.\n    </p>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.quality-review-content-editing.note\">\n      *There is a 5,000-word minimum charge for all editing services.\n    </p>\n  </div>\n</div>",
    "quality-review-content-editing-plus": "<div class=\"quality-review-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.quality-review-content-editing-plus.prereq\">\n      Prerequisite: Omni Content Editing Plus. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing-plus.p1\">\n      Our Quality Review - Content Editing Plus service provides a final check to make sure your revised manuscript is sound before it goes into production—for a fraction of the price of your original edit.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing-plus.p2\">\n      After you review and revise your edited manuscript, you may want an editor to check your work to ensure that you've done it correctly and haven't created new errors in the process.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.quality-review-content-editing-plus.p3\">\n      Content Editing, by its very nature, involves extensive revisions to your manuscript — for example, restructuring sentences and adding material. With the Quality Review, an editor will not only review the work you've done on the manuscript in response to the editing, but ensure that you've adequately addressed all of the queries and comments.\n    </p>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.quality-review-content-editing-plus.note\">\n      *There is a 5,000-word minimum charge for all editing services.\n    </p>\n  </div>\n</div>",
    "editorial-assistant-copyediting": "<div class=\"editorial-assistant-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.editorial-assistant-copyediting.prereq\">\n      Prerequisite: Omni Copyediting. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-copyediting.p1\">\n      Your editorial assistant will review each change and suggestion given during the Copyediting service and take action on each one.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-copyediting.p2\">\n      Going through an edited manuscript can sometimes be a time-consuming process for even the most experienced author, as it requires decisions be made regarding each of the revisions, comments, and recommendations. For our busiest authors and for authors who may be unsure of their own ability to make the needed changes, Omni offers the Editorial Assistant service, in which a professional editor handles the editing work for the author.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-copyediting.p3\">\n      Your editorial assistant will review each change and suggestion given during the copyediting and take action on each one, accepting changes, rewriting sentences, resolving queries and handling other revisions suggested by the original copyeditor. This service is ideal for authors who approve of most of the editor's work on their manuscript and do not wish to work with tracked changes in their manuscript.\n    </p>\n    <p class=\"mb-3 fw-medium editable-field\" style=\"color: #2b2219;\" data-block-key=\"service.editorial-assistant-copyediting.cost\">\n      Estimate of cost is provided with your completed Copyedit.\n    </p>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.editorial-assistant-copyediting.note\">\n      Please note: There may be some questions or comments from the editor that you, the author, will need to address before moving forward with this service.\n    </p>\n  </div>\n</div>",
    "editorial-assistant-line-edit": "<div class=\"editorial-assistant-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.editorial-assistant-line-edit.prereq\">\n      Prerequisite: Omni Line Edit. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-line-edit.p1\">\n      Your editorial assistant will review each change and suggestion given during the Line Edit service and take action on each one.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-line-edit.p2\">\n      Going through an edited manuscript can sometimes be a time-consuming process for even the most experienced author, as it requires decisions be made regarding each of the revisions, comments, and recommendations. For our busiest authors and for authors who may be unsure of their own ability to make the needed changes, Omni offers the Editorial Assistant service, in which a professional editor handles the editing work for the author.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-line-edit.p3\">\n      Your editorial assistant will review each change and suggestion given during the line edit and take action on each one, accepting changes, rewriting sentences, resolving queries and handling other revisions as suggested by the line editor. This service is ideal for authors who approve of most of the editor's work on their manuscript and do not wish to work with tracked changes in their manuscript.\n    </p>\n    <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n      <p class=\"mb-1 editable-field\" data-block-key=\"service.editorial-assistant-line-edit.duration\"><strong style=\"color: #ad7d42;\">Duration: </strong> 2-3 weeks</p>\n      <p class=\"mb-0 editable-field\" data-block-key=\"service.editorial-assistant-line-edit.cost\"><strong style=\"color: #ad7d42;\">Cost: </strong> Estimate provided with your completed Line Edit.</p>\n    </div>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.editorial-assistant-line-edit.note\">\n      Please note: There may be some questions or comments from the editor that you, the author, will need to address before moving forward with this service.\n    </p>\n  </div>\n</div>",
    "editorial-assistant-content-edit": "<div class=\"editorial-assistant-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.editorial-assistant-content-edit.prereq\">\n      Prerequisite: Omni Content Edit. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit.p1\">\n      Your editorial assistant will review each change and suggestion given during the Content Edit service and take action on each one.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit.p2\">\n      Going through an edited manuscript can sometimes be a time-consuming process for even the most experienced author, as it requires decisions be made regarding each of the revisions, comments, and recommendations. For our busiest authors and for authors who may be unsure of their own ability to make the needed changes, Omni offers the Editorial Assistant service, in which a professional editor handles the editing work for the author.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit.p3\">\n      Your editorial assistant will review each change and suggestion given during the Content Edit and take action on each one, accepting changes, rewriting sentences, resolving queries and handling other revisions as suggested by the content editor. This service is ideal for authors who approve of most of the editor's work on their manuscript and do not wish to work with tracked changes in their manuscript.\n    </p>\n    <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n      <p class=\"mb-1 editable-field\" data-block-key=\"service.editorial-assistant-content-edit.duration\"><strong style=\"color: #ad7d42;\">Duration: </strong> 2-3 weeks</p>\n      <p class=\"mb-0 editable-field\" data-block-key=\"service.editorial-assistant-content-edit.cost\"><strong style=\"color: #ad7d42;\">Cost: </strong> Estimate provided with your completed content edit.</p>\n    </div>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.editorial-assistant-content-edit.note\">\n      Please note: There may be some questions or comments from the editor that you, the author, will need to address before moving forward with this service.\n    </p>\n  </div>\n</div>",
    "editorial-assistant-content-edit-plus": "<div class=\"editorial-assistant-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.editorial-assistant-content-edit-plus.prereq\">\n      Prerequisite: Omni Content Edit Plus. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit-plus.p1\">\n      Your editorial assistant will review each change and suggestion given during the Content Edit Plus service and take action on each one.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit-plus.p2\">\n      Going through an edited manuscript can sometimes be a time-consuming process for even the most experienced author, as it requires decisions be made regarding each of the revisions, comments, and recommendations. For our busiest authors and for authors who may be unsure of their own ability to make the needed changes, Omni offers the Editorial Assistant service, in which a professional editor handles the editing work for the author.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-assistant-content-edit-plus.p3\">\n      Your editorial assistant will review each change and suggestion given during the Content Editor Plus service and take action on each one, accepting changes, rewriting sentences, resolving queries ,and handling other revisions as suggested by the Content Editor Plus service. This service is ideal for authors who approve of most of the editor's work on their manuscript and do not wish to work with tracked changes in their manuscript.\n    </p>\n    <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n      <p class=\"mb-1 editable-field\" data-block-key=\"service.editorial-assistant-content-edit-plus.duration\"><strong style=\"color: #ad7d42;\">Duration: </strong> 2-3 weeks</p>\n      <p class=\"mb-0 editable-field\" data-block-key=\"service.editorial-assistant-content-edit-plus.cost\"><strong style=\"color: #ad7d42;\">Cost: </strong> Estimate provided with your completed content edit plus.</p>\n    </div>\n    <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.editorial-assistant-content-edit-plus.note\">\n      Please note: There may be some questions or comments from the editor that you, the author, will need to address before moving forward with this service.\n    </p>\n  </div>\n</div>",
    "cover-copy-polish": "<div class=\"cover-copy-polish-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.cover-copy-polish.p1\">\n      With Omni Cover Copy Polishing, the ideas you provide will allow us to create intriguing copy that can help you clinch the sale. Our professional copywriting staff will mold the text that you provide into marketable material by polishing the hardcover flaps, back cover copy, author bio and keynote, in addition to any other cover material you have submitted.\n    </p>\n    <p class=\"mb-0 editable-field\" data-block-key=\"service.cover-copy-polish.p2\">\n      Create intriguing cover text and catch the attention of book buyers with this professional copywriting service. The typical timeline for this service is <strong>one week</strong>, depending on our queue and the complexity of your work.\n    </p>\n  </div>\n</div>",

  "evaluation-services": "<div class=\"evaluation-services-overview-content\">\n  <p class=\"mb-4 editable-field\" style=\"color: #57534e; font-size: 0.98rem; line-height: 1.7;\" data-block-key=\"service.evaluation-services.intro\">\n    One of the key features that makes an Omni book distinct from other self-published books is our professional editorial evaluation. The evaluation is included in certain publishing packages and is available to purchase separately as well.\n  </p>\n  <div class=\"evaluation-section-block mb-4\">\n    <h4 class=\"editorial-accent-title fw-bold mb-2 editable-field\" style=\"color: #d9534f; font-size: 1.25rem;\" data-block-key=\"service.evaluation-services.rx_title\">\n      Editorial Rx Referral\n    </h4>\n    <p class=\"editorial-section-p mb-3 editable-field\" style=\"color: #57534e; font-size: 0.98rem; line-height: 1.7;\" data-block-key=\"service.evaluation-services.rx_desc\">\n      Through this service, an evaluator will recommend the services of an appropriate editorial specialist—from a copyeditor or content editor to a developmental editor or book doctor.\n    </p>\n    <blockquote class=\"editorial-testimonial-quote\" style=\"margin: 18px 0; padding: 16px 20px; border-left: 4px solid #d9534f; background: rgba(217, 83, 79, 0.04); border-radius: 0 8px 8px 0; font-style: italic; color: #444;\">\n      <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.evaluation-services.rx_quote\">\n        \"With the various points to examine and adjust in mind, I re-read This Golden Land and made changes along the way. These were excellent points, by the way, and very helpful to me for cleaning up the manuscript.\"\n      </p>\n      <footer class=\"editorial-quote-author editable-field\" style=\"font-style: normal; font-weight: 600; color: #666; font-size: 0.88rem;\" data-block-key=\"service.evaluation-services.rx_author\">\n        -Barbara Wood, author of This Golden Land\n      </footer>\n    </blockquote>\n  </div>\n  <div class=\"evaluation-section-block mb-4\">\n    <h4 class=\"editorial-accent-title fw-bold mb-2 editable-field\" style=\"color: #d9534f; font-size: 1.25rem;\" data-block-key=\"service.evaluation-services.eval_title\">\n      Editorial Evaluation Services\n    </h4>\n    <p class=\"editorial-section-p mb-0 editable-field\" style=\"color: #57534e; font-size: 0.98rem; line-height: 1.7;\" data-block-key=\"service.evaluation-services.eval_desc\">\n      Regardless of your publishing goals, the editorial quality of your work matters—no one wants to read a book that's riddled with typos and grammatical errors. However, even the best writers make occasional mistakes. Omni provides editorial services that will help you make your book the best it can be.\n    </p>\n  </div>\n  <div class=\"publishing-packages-container mt-4\">\n    <div class=\"publishing-package-card\" onclick=\"selectSubcategoryById('evaluation-services', 'editorial-evaluation')\" style=\"cursor: pointer;\">\n      <div class=\"publishing-package-card-header\">\n        <h5 class=\"publishing-package-card-title m-0 editable-field\" data-block-key=\"service.editorial-evaluation.title\">Evaluation Editorial</h5>\n        <span class=\"publishing-package-arrow-badge\"><i class=\"bi bi-arrow-right-short\"></i></span>\n      </div>\n      <p class=\"publishing-package-card-summary editable-field\" data-block-key=\"service.editorial-evaluation.desc\">\n        Editorial Evaluation Services Regardless of your publishing goals, the editorial quality of your work matters—no one wants to read a book that's riddled with typos and grammatical errors. However, even the best writers make occasional mistakes. Omni provides editorial services that will help you make your book the best it can be.\n      </p>\n    </div>\n  </div>\n</div>",
  "editorial-evaluation": "<div class=\"editorial-evaluation-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.lead_p\">\n      No matter how small or big an audience you want to reach, the editorial quality of your work matters. You've worked hard to get your manuscript written; now let Omni provide you with services that will help you make it the best it can be.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.p1\">\n      The Editorial Evaluation is a manuscript checkup that assesses your work to be sure that it has fulfilled the basic requirements of a published book. The editorial evaluator will not only provide you with a general overview of your manuscript but will also educate you through constructive comments on how to write a better book.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.p2\">\n      The Editorial Evaluation is a detailed report on the observations of an evaluator about the strengths and weaknesses of your manuscript (rather than an editing of your manuscript). At the end of the evaluation, an Editorial Rx Referral will recommend the services of an appropriate editorial specialist—from a copyeditor or content editor to a developmental editor. You may then choose to purchase those services from Omni. If you do choose to purchase an editorial service, our staff will assign your book to a specialist who will address the issues raised in the Editorial Evaluation and give your manuscript the professional attention that it would receive at a traditional publishing house. You may also choose to use your own freelance editor or make the recommended changes yourself.\n    </p>\n    <blockquote class=\"editorial-testimonial-quote\" style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173, 125, 66, 0.05); border-radius: 0 8px 8px 0; font-style: italic; color: #333;\">\n      <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.editorial-evaluation.quote\">\n        \"I appreciate all the editorial work that went into the analysis – I was very impressed with the job Omni did with my book. The analysis was thorough, clear, and very helpful. Thank you again for all your assistance on making his Golden Land even better!\"\n      </p>\n      <footer style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\" class=\"editable-field\" data-block-key=\"service.editorial-evaluation.quote_author\">\n        —Barbara Wood, author of This Golden Land\n      </footer>\n    </blockquote>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.p3\">\n      The Editorial Evaluation also qualifies you for possible selection to our prestigious Editor's Choice program.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.p4\">\n      Here are a few examples of questions that are answered in Editorial Evaluations depending on your book's genre.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.p5\">\n      Please note: The Editorial Evaluation is not a replacement for Omni’s editorial services. Rather, it is a preliminary diagnostic tool, examining several sections of the manuscript in detail, to pinpoint areas in need of improvement. Evaluators offer examples of items that could be strengthened and give critique and commentary across a range of topics.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.editorial-evaluation.p6\">\n      The Editorial Evaluation fee is based on industry standard manuscript word count of 100,000 words or less. For manuscripts above 100,000 words, the author may choose to have approximately the first 100,000 words assessed during the Editorial Evaluation. If the author wishes to have the full manuscript evaluated, an additional fee for each 50,000 words over 100,000 will be required. Should the author purchase one of our editing services, the full manuscript will be edited line by line.\n    </p>\n    <div class=\"editorial-callout-notice p-3 mb-3 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n      <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.editorial-evaluation.credit_note\">\n        Note: You have the option to work with your editor or make changes yourself. However, should you decide to purchase any of our Editorial Services, you will receive a $299 credit which will be deducted from the overall editing cost.\n      </p>\n    </div>\n    <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n      <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n      <span style=\"color: #57534e;\" class=\"editable-field\" data-block-key=\"service.editorial-evaluation.duration\">2-3 Weeks</span>\n    </div>\n  </div>\n</div>",
  "evaluation-editorial": "<div class=\"evaluation-editorial-content\">\n  <p class=\"mb-4 editable-field\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\" data-block-key=\"service.editorial-evaluation.intro_p\">\n    Editorial Evaluation Services Regardless of your publishing goals, the editorial quality of your work matters—no one wants to read a book that's riddled with typos and grammatical errors. However, even the best writers make occasional mistakes. Omni provides editorial services that will help you make your book the best it can be.\n  </p>\n  <div class=\"package-card-block mb-4\">\n    <h5 class=\"fw-bold mb-2 editable-field\" style=\"color: #d9534f; font-size: 1.25rem;\" data-block-key=\"service.editorial-evaluation.sub_heading\">\n      Editorial Evaluation\n    </h5>\n    <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.96rem; line-height: 1.72;\" data-block-key=\"service.editorial-evaluation.eval_p\">\n      Omni experienced editorial evaluators will review your manuscript and provide you with a general overview of your manuscript as well as give constructive comments on how to better write your book.\n    </p>\n  </div>\n</div>",
  "developmental-editing": "<div class=\"developmental-editing-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-1 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.developmental-editing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                          Prescribed by Editorial Evaluation only. Please speak with your editorial consultant for more information.\n                        </p>\n                        <p class=\"fst-italic mb-0 fw-semibold editable-field\" style=\"color: #ad7d42; font-size: 0.92rem;\" data-block-key=\"service.developmental-editing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                          Please Note: A Developmental Edit includes FREE Content Editing and Quality Review.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.developmental-editing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                          The Omni Developmental Editing service combines three editorial services into one package: First, a developmental editor evaluates the manuscript at the paragraph, chapter, and book levels and makes suggestions throughout the manuscript to identify big-picture areas that need work.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fcfbf9; border: 1px solid #ebd9c4;\">\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.94rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.developmental-editing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                              <strong>For fiction works</strong>, the editor will analyze the readership and genre to determine whether the content is appropriate. He will then examine essential considerations such as plot, pace, characterization and dialogue.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.developmental-editing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                              <strong>For nonfiction titles</strong>, the editor will analyze the readership, purpose, and possible uses of the work to determine that the content is complete and appropriate; that concepts are developed adequately; that material is well organized; and that illustrations, tables, and lists are used effectively throughout.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.developmental-editing.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                          Authors can choose to make improvements suggested by the developmental editor themselves or purchase the services of a Book Doctor to help them make alterations. (If applicable, a price estimate for book doctoring is included with the completed developmental edit.) Once big-picture changes have been made, the second step, a free Content Edit, begins; the content editor will check the manuscript for errors in grammar, spelling, and punctuation. And third, the manuscript will receive a quality review to ensure the manuscript is editorially sound before it goes into production.\n                        </p>\n\n                        <blockquote \n                          class=\"editorial-testimonial-quote\"\n                          style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173; border-radius: 0 8px 8px 0; font-style: italic; color: #333;\"\n                        >\n                          <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.developmental-editing.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('developmental-editing', this)\">\n                            \"I am THRILLED with the edit so far! I've never had a developmental edit, and it's so cool to 'hear' someone else's voice regarding the material. What's more, the editor has targeted areas that I subconsciously knew needed work, but just didn't hear my conscious voice telling me how to correct. Please let her know how excited I am and how far her input had surpassed what I thought I was paying for.\"\n                          </p>\n                          <footer style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\">\n                            — Eric Rankin, author of <em>The Aquarians</em>\n                          </footer>\n                        </blockquote>\n                      </div>\n                    </div>",
  "book-doctor": "<div class=\"book-doctor-detail-content\">\n  <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n    <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.book-doctor.prereq\">\n      Prerequisite: Omni Developmental Edit. Please speak with your editorial consultant for more information.\n    </p>\n  </div>\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.book-doctor.p1\">\n      Following the advice of a professional editor takes time and careful consideration. Developmental Editing, in particular, often requires the author to rewrite or reorganize the manuscript to enhance material. Hiring a book doctor may be the best choice for authors who don't have the time or ability to make the big-picture changes recommended by a developmental editor.\n    </p>\n    <p class=\"mb-3 editable-field\" data-block-key=\"service.book-doctor.p2\">\n      A book doctor makes the changes recommended by the developmental editor and approved by the author. A price quote for the book doctor will be provided with the completed developmental edit.\n    </p>\n    <p class=\"mb-3 fw-medium editable-field\" style=\"color: #2b2219;\" data-block-key=\"service.book-doctor.p3\">\n      After completion of Book Doctoring, Content Editing and a Quality Review will be provided at no extra cost.\n    </p>\n    <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n      <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n      <span style=\"color: #57534e;\">Estimate based on work required and detailed through the Developmental Edit.</span>\n    </div>\n  </div>\n</div>",
  "small-book-review-with-editing-under-5-000-words": "<div class=\"small-book-review-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                          We know you’ve put a lot of energy and dedication into your manuscript, but even experienced authors overlook their own mistakes sometimes. Since the editorial quality of your book will have an impact on your readers and its ultimate success, it’s important to have another set of professional eyes look over your book before it’s published.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                          The Omni editors carefully review your full manuscript (under 5,000 words) and provide you with the edits best suited to your book. This all-inclusive service is an excellent option for children’s books. We won’t just point out what’s not working; we can help you decide exactly how to fix it.\n                        </p>\n\n                        <p class=\"fw-semibold mb-2 editable-field\" style=\"color: #2b2219;\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                          Here’s what to expect:\n                        </p>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            <strong>Line Editing: </strong>We perfect your spelling, punctuation, capitalization, grammar, and syntax. And we’ll provide recommendations for word choice and improving overall readability.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            <strong>Content Editing: </strong>We confirm the consistency of information and ideas throughout the whole book, and we also focus on more extensive sentence restructuring.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            Our editors use Microsoft Word® to track their changes, so you always <strong>retain control over final edits.</strong>\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            Our editors typically turn your manuscript around in <strong>three to four weeks.</strong> After that time, your editor will reach out with their edits and suggestions for improvement.\n                          </li>\n                        </ul>\n\n                        <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"fst-italic mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            <strong>Please Note: </strong>This service does not include our advanced editorial services, such as Developmental Editing. Rather, it is a combination of our Line Editing and Content Editing services with a report from the editor.\n                          </p>\n                        </div>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.1rem;\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                          More About | Small Book Review with Editing (Under 5,000 Words)\n                        </h5>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                          Almost nothing compares to publishing a book that is polished and clear. Choose to make your book the best it can be with our combined review and editing service. The typical timeline for this service is <strong>three to four weeks</strong>, depending on the work queue and the complexity of your manuscript. Call <strong>1-800-AUTHORS (288-4677)</strong> for more information, or to purchase this service.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"fst-italic fw-medium mb-2 editable-field\" style=\"color: #78716c; font-size: 0.92rem;\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                            *Please note:\n                          </p>\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-2 fst-italic\" style=\"color: #57534e; font-size: 0.9rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('small-book-review-with-editing-under-5-000-words', this)\">\n                              Omni accepts a very low margin of error in each completed edit. Our professional in-house editorial staff reviews each editorial service for quality assurance – an edit won’t be returned to an author until fewer than three percent of the original errors remain.\n                            </li>\n                            <li>\n                              Upon reviewing your edited manuscript, if you believe that an unsatisfactory number of errors have been addressed, please create a list of the errors and the page numbers on which they appear and email it to <a href=\"mailto:editorial@omnivirtualsolution.com\" class=\"editable-field editorial-email-link\" data-block-key=\"service.small-book-review-with-editing-under-5-000-words.email\" style=\"color: #ad7d42; text-decoration: underline; font-weight: 600;\">editorial@omnivirtualsolution.com</a>. We will review the list with you and address your concern.\n                            </li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "copyediting": "<div class=\"copyediting-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.copyediting.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('copyediting', this)\">\n                          Prescribed by Editorial Evaluation only. Please do not order without first speaking with your editorial consultant.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.copyediting.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('copyediting', this)\">\n                          An experienced copyeditor will check your manuscript carefully, correcting errors in spelling, grammar, and punctuation. In addition, the copyeditor will verify cross-references and impose an industry-standard style.\n                        </p>\n\n                        <blockquote \n                          class=\"editorial-testimonial-quote\"\n                          style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173; border-radius: 0 8px 8px 0; font-style: italic; color: #333;\"\n                        >\n                          <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.copyediting.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('copyediting', this)\">\n                            \"I took my editorial consultant's comment to heart that regardless of the quality of the book's content and message, grammatical errors will cause the public to lose respect for it. As a structural engineer, I can appreciate that since I regularly submit documents and have them submitted to me. The presentation is as important as the content. The editor's contribution has greatly enhanced my manuscript and was well worth the cost. I would recommend the use of an editor to any serious author.\"\n                          </p>\n                          <footer style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\">\n                            - Bill Stahl, author of <em>The Bible's Story of Salvation</em>\n                          </footer>\n                        </blockquote>\n\n                        <p class=\"fst-italic mb-0 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.copyediting.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('copyediting', this)\">\n                          *There is a 5,000-word minimum charge for all editing services.\n                        </p>\n                      </div>\n                    </div>",
  "line-editing": "<div class=\"line-editing-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.line-editing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                          Some manuscripts simply require more work than others. When heavy copyediting is required, an editor will check the manuscript for more pervasive errors in spelling, grammar, and punctuation. The editor will also address syntax and word choice and make light recommendations for improving the overall readability of the work.\n                        </p>\n\n                        <blockquote \n                          class=\"editorial-testimonial-quote\"\n                          style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173; border-radius: 0 8px 8px 0; font-style: italic; color: #333;\"\n                        >\n                          <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.line-editing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                            \"I would like to thank the editor for a heroic job. My mother was apprehensive ... her book is intended to convey the thoughts of a child. The quirky language reflects this, and she was afraid the child's \\\"voice\\\" might be lost in the editing. I read the first few chapters of the edited manuscript to her. She was delighted! It is clear that this is a very conscientious editor and one to be trusted.\"\n                          </p>\n                          <footer style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\">\n                            Virginia Merrill, author of <em>Believe in Guardian Angels</em>\n                          </footer>\n                        </blockquote>\n\n                        <p class=\"fst-italic mb-2 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.line-editing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                          * Note: Line Editing is also available in Spanish. For more information, speak with your publishing consultant.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.line-editing.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                          *There is a 5,000-word minimum charge for all editing services.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" style=\"font-size: 0.95rem;\" data-block-key=\"service.line-editing.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                          Leave it to our editorial specialists to take your book to the next level. The typical timeline for this service is <strong>six to eight weeks</strong>, depending on our queue and the complexity of your work.\n                        </p>\n\n                        <p class=\"fst-italic text-muted mb-0 editable-field\" style=\"font-size: 0.82rem; line-height: 1.6;\" data-block-key=\"service.line-editing.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('line-editing', this)\">\n                          Disclaimer: Prices listed do not include applicable taxes (such as sales, use, excise, value-added, goods and services, or other tax), which will be added to the total at the time of purchase. Prices listed do include the copies of the book; the cost of shipping and handling will be calculated and charged after your book is made available for sale.\n                        </p>\n                      </div>\n                    </div>",
  "content-editing": "<div class=\"content-editing-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.content-editing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                          Prescribed by Editorial Evaluation only. Please do not order without first speaking with your editorial consultant.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.content-editing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                          In addition to performing the functions of a line edit, a content editor will work to ensure the general accuracy and consistency of content and focus on more extensive restructuring of sentences.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fcfbf9; border: 1px solid #ebd9c4;\">\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.94rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.content-editing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                              <strong>For fiction titles, </strong>the editor will focus on maintaining consistency of details in the plot, characters and setting.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.content-editing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                              <strong>For nonfiction titles, </strong>the editor will monitor consistency of information and ideas.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <p class=\"fst-italic mb-3 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.content-editing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                          *There is a 5,000-word minimum charge for all editing services.\n                        </p>\n\n                        <p class=\"mb-0 editable-field\" style=\"font-size: 0.95rem;\" data-block-key=\"service.content-editing.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing', this)\">\n                          Leave it to our editorial specialists to take your book to the next level. The typical timeline for this service is <strong>six to eight weeks</strong>, depending on our queue and the complexity of your work.\n                        </p>\n                      </div>\n                    </div>",
  "content-editing-plus": "<div class=\"content-editing-plus-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.content-editing-plus.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          Prescribed by Editorial Evaluation only. Please do not order without first speaking with your editorial consultant.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.content-editing-plus.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          This service is ideal for manuscripts that need more work on sentence structure and grammar than basic Content Editing can provide. Content Editing Plus is especially suitable for translations or manuscripts written by authors whose second language is English.\n                        </p>\n\n                        <blockquote \n                          class=\"editorial-testimonial-quote\"\n                          style=\"margin: 22px 0; padding: 16px 22px; border-left: 4px solid #ad7d42; background: rgba(173; border-radius: 0 8px 8px 0; font-style: italic; color: #333;\"\n                        >\n                          <p class=\"mb-2 editable-field\" style=\"font-size: 0.95rem; line-height: 1.6;\" data-block-key=\"service.content-editing-plus.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                            \"It is difficult to imagine the best editor at HarperCollins doing a better job than my Omni editor. Editing services through Omni are equal to the finest brick and mortar publishing houses and far more timely.\"\n                          </p>\n                          <footer style=\"font-style: normal; font-weight: 600; color: #78716c; font-size: 0.88rem;\">\n                            -Michael R Zomber, author of <em>Shogun Iemitsu</em>\n                          </footer>\n                        </blockquote>\n\n                        <p class=\"fst-italic mb-3 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.content-editing-plus.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          *There is a 5,000-word minimum charge for all editing services.\n                        </p>\n\n                        <p class=\"mb-0 editable-field\" style=\"font-size: 0.95rem;\" data-block-key=\"service.content-editing-plus.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          Leave it to our editorial specialists to take your book to the next level. The typical timeline for this service is <strong>six to eight weeks</strong>, depending on our queue and the complexity of your work.\n                        </p>\n                      </div>\n                    </div>\n                  ) : (selectedService?.slug === 'cover-copy-polish' && !isCurrentSubcategoryOverview) ? (\n                    \n                    <div class=\"cover-copy-polish-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.content-editing-plus.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          With Omni Cover Copy Polishing, the ideas you provide will allow us to create intriguing copy that can help you clinch the sale. Our professional copywriting staff will mold the text that you provide into marketable material by polishing the hardcover flaps, back cover copy, author bio and keynote, in addition to any other cover material you have submitted.\n                        </p>\n\n                        <p class=\"mb-0 editable-field\" data-block-key=\"service.content-editing-plus.p7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('content-editing-plus', this)\">\n                          Create intriguing cover text and catch the attention of book buyers with this professional copywriting service. The typical timeline for this service is <strong>one week</strong>, depending on our queue and the complexity of your work.\n                        </p>\n                      </div>\n                    </div>",
  "professional-indexing": "<div class=\"professional-indexing-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.professional-indexing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          Please speak with your editorial consultant for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.professional-indexing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          Our professional indexers will provide you with an industry-standard, two-level topical index that is personalized to provide maximum usability for the book's target audience.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.professional-indexing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          The professional indexer analyzes your entire book, anticipating line items your reader will most likely want to find and listing them in an intuitive, accessible manner.\n                        </p>\n                        <p class=\"mb-2 editable-field\" data-block-key=\"service.professional-indexing.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          Before handcrafting your one-of-a-kind index, our professional indexer considers the following four elements that make your book unique:\n                        </p>\n\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-1\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.professional-indexing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">Focus</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-indexing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">Purpose</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-indexing.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">Audience</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-indexing.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">Organization</li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.professional-indexing.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          The resulting high-quality index is the standard found throughout the publishing industry.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 text-muted editable-field\" style=\"font-size: 0.9rem;\" data-block-key=\"service.professional-indexing.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          *There is a 5,000-word minimum charge for all editing services.\n                        </p>\n\n                        <p class=\"fst-italic text-muted mb-0 editable-field\" style=\"font-size: 0.9rem; line-height: 1.65;\" data-block-key=\"service.professional-indexing.p7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-indexing', this)\">\n                          Please note: We craft indexes from the final, formatted, author-approved pages. Changes made after indexing may alter the pagination and detract from the index's usability or may lead to additional charges to correct the index.\n                        </p>\n                      </div>\n                    </div>",
  "computer-generated-keyword-indexing-up-to-500-entries": "<div class=\"keyword-indexing-500-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-500-entries.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-500-entries', this)\">\n                          A computer-generated keyword index lists a page number for a key term each time it occurs in the book. You simply provide Omni with a list of words that you want to appear in the index. Omni will create an index by tagging the selected words during the production process. The resulting alphabetical list of keywords gives the page numbers for each occurrence of the word.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-500-entries.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-500-entries', this)\">\n                          The success of this type of index depends entirely on the key words you chose. The choice of words needs to be carefully thought through. Do not use simple words or words that repeat constantly throughout the text. For example, if you are writing a cookbook, do not index the word egg. Every time the word \"egg\" is mentioned, the computer will index that page. We presume that egg would show up on many recipe pages. If words are not chosen carefully, the resulting index can be overly long and unusable.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-500-entries.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-500-entries', this)\">\n                          Please note: a concordance-type index has no logical organization other than alphabetization, and only exact word matches can be indexed using the approach.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" style=\"font-size: 0.93rem; line-height: 1.68;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-500-entries.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-500-entries', this)\">\n                          *We highly recommend our Professional Index service if you require an industry-standard index. A computer cannot do what a professional, human indexer can—evaluate the significance of each occurrence of a word and whether it's really important to list, develop appropriate cross references and sub-entries, phrase entries in the most useful way, and more.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timing: </span>\n                          <span style=\"color: #57534e;\">Adds two weeks to the design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "computer-generated-keyword-indexing-up-to-700-entries": "<div class=\"keyword-indexing-700-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-700-entries.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-700-entries', this)\">\n                          A computer-generated keyword index lists a page number for a key term each time it occurs in the book. You simply provide Omni with a list of words that you want to appear in the index. Omni will create an index by tagging the selected words during the production process. The resulting alphabetical list of keywords gives the page numbers for each occurrence of the word.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-700-entries.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-700-entries', this)\">\n                          The success of this type of index depends entirely on the key words you chose. The choice of words needs to be carefully thought through. Do not use simple words or words that repeat constantly throughout the text. For example, if you are writing a cookbook, do not index the word egg. Every time the word \"egg\" is mentioned, the computer will index that page. We presume that egg would show up on many recipe pages. If words are not chosen carefully, the resulting index can be overly long and unusable.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-700-entries.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-700-entries', this)\">\n                          Please note: a concordance-type index has no logical organization other than alphabetization, and only exact word matches can be indexed using the approach.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" style=\"font-size: 0.93rem; line-height: 1.68;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-700-entries.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-700-entries', this)\">\n                          *We highly recommend our Professional Index service if you require an industry-standard index. A computer cannot do what a professional, human indexer can—evaluate the significance of each occurrence of a word and whether it's really important to list, develop appropriate cross references and sub-entries, phrase entries in the most useful way, and more. Librarians and reviewers consider a computer-generated word list not simply less useful but a liability to a book.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timing: </span>\n                          <span style=\"color: #57534e;\">Adds two weeks to the design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "computer-generated-keyword-indexing-up-to-1-000-entries": "<div class=\"keyword-indexing-1000-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-1-000-entries.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-1-000-entries', this)\">\n                          A computer-generated keyword index lists a page number for a key term each time it occurs in the book. You simply provide Omni with a list of words that you want to appear in the index. Omni will create an index by tagging the selected words during the production process. The resulting alphabetical list of keywords gives the page numbers for each occurrence of the word.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-1-000-entries.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-1-000-entries', this)\">\n                          The success of this type of index depends entirely on the key words you chose. The choice of words needs to be carefully thought through. Do not use simple words or words that repeat constantly throughout the text. For example, if you are writing a cookbook, do not index the word egg. Every time the word \"egg\" is mentioned, the computer will index that page. We presume that egg would show up on many recipe pages. If words are not chosen carefully, the resulting index can be overly long and unusable.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-1-000-entries.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-1-000-entries', this)\">\n                          Please note: a concordance-type index has no logical organization other than alphabetization, and only exact word matches can be indexed using the approach.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" style=\"font-size: 0.93rem; line-height: 1.68;\" data-block-key=\"service.computer-generated-keyword-indexing-up-to-1-000-entries.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-up-to-1-000-entries', this)\">\n                          *We highly recommend our Professional Index service if you require an industry-standard index. A computer cannot do what a professional, human indexer can—evaluate the significance of each occurrence of a word and whether it's really important to list, develop appropriate cross references and sub-entries, phrase entries in the most useful way, and more. Librarians and reviewers consider a computer-generated word list not simply less useful but a liability to a book.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timing: </span>\n                          <span style=\"color: #57534e;\">Adds two weeks to the design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "computer-generated-keyword-indexing-custom-quote": "<div class=\"keyword-indexing-custom-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.computer-generated-keyword-indexing-custom-quote.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-custom-quote', this)\">\n                          An index of over 1,000 will require a custom quote. Contact your PSA for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-custom-quote.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-custom-quote', this)\">\n                          A computer-generated keyword index lists a page number for a key term each time it occurs in the book. You simply provide Omni with a list of words that you want to appear in the index. Omni will create an index by tagging the selected words during the production process. The resulting alphabetical list of keywords gives the page numbers for each occurrence of the word.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.computer-generated-keyword-indexing-custom-quote.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-custom-quote', this)\">\n                          The success of this type of index depends entirely on the key words you chose. The choice of words needs to be carefully thought through. Do not use simple words or words that repeat constantly throughout the text. For example, if you are writing a cookbook, do not index the word egg. Every time the word \"egg\" is mentioned, the computer will index that page. We presume that egg would show up on many recipe pages. If words are not chosen carefully, the resulting index can be overly long and unusable.\n                        </p>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.computer-generated-keyword-indexing-custom-quote.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-custom-quote', this)\">\n                          Please note: a concordance-type index has no logical organization other than alphabetization, and only exact word matches can be indexed using the approach.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" style=\"font-size: 0.93rem; line-height: 1.68;\" data-block-key=\"service.computer-generated-keyword-indexing-custom-quote.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('computer-generated-keyword-indexing-custom-quote', this)\">\n                          *We highly recommend our Professional Index service if you require an industry-standard index. A computer cannot do what a professional, human indexer can—evaluate the significance of each occurrence of a word and whether it's really important to list, develop appropriate cross references and sub-entries, phrase entries in the most useful way, and more. Librarians and reviewers consider a computer-generated word list not simply less useful but a liability to a book.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timing: </span>\n                          <span style=\"color: #57534e;\">Adds two weeks to the design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "proofreading": "<div class=\"proofreading-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.94rem;\" data-block-key=\"service.proofreading.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('proofreading', this)\">\n                          Prerequisite: An Omni core editorial service, as recommended. Please speak with your editorial consultant for more information.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.proofreading.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('proofreading', this)\">\n                          As any publishing professional knows, the process of converting a manuscript into a published book is not 100 percent foolproof. Even manuscripts that have undergone a Quality Review can have the occasional remaining error, as even the best copyeditor in the business or the most careful author can inadvertently overlook or create a few mistakes. In fact, for this reason, traditional publishers usually proofread a manuscript twice. This final polish is highly recommended.\n                        </p>\n\n                        <p class=\"fst-italic mb-2 editable-field\" style=\"color: #44403c; font-size: 0.95rem;\" data-block-key=\"service.proofreading.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('proofreading', this)\">\n                          \"I must comment on the meticulous job done by all the editors, including the last. She found things that we all had missed ... It's downright scary that I teach ENGLISH!\"\n                        </p>\n\n                        <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.proofreading.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('proofreading', this)\">\n                          -Robin M. Berard, author of King Tut and the Girl Who Loved Him\n                        </p>\n                      </div>\n                    </div>",
  "do-it-yourself-audiobook": "<div class=\"diy-audiobook-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.do-it-yourself-audiobook.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          Expand your audience and reach with the power of audiobooks, an increasingly popular and preferred format.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.do-it-yourself-audiobook.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          Now you can bring your book to life with your own voice.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.do-it-yourself-audiobook.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          Effortlessly transform your written words into an immersive audiobook using our partner DIY Audiobook platform, \n                          <a \n                            href=\"https://myaudiobookrecorder.com/\" \n                            target=\"_blank\" \n                            rel=\"noopener noreferrer\" \n                            style=\"color: #ad7d42; font-weight: 600; text-decoration: underline;\"\n                          >\n                            Myaudiobookrecorder.com.\n                          </a>\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.do-it-yourself-audiobook.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          This service empowers you to record and produce your audiobook, without needing any audio editing experience.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.do-it-yourself-audiobook.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          Key Features:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.do-it-yourself-audiobook.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">Easy-to-use recording and editing tools</li>\n                          <li class=\"editable-field\" data-block-key=\"service.do-it-yourself-audiobook.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">Six months of access to the virtual recording studio</li>\n                          <li class=\"editable-field\" data-block-key=\"service.do-it-yourself-audiobook.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">Availability of your audiobook through Overdrive, Audible.com, Amazon.com, and iTunes</li>\n                          <li class=\"editable-field\" data-block-key=\"service.do-it-yourself-audiobook.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">ISBN registration</li>\n                        </ul>\n\n                        <p class=\"fst-italic mb-0 editable-field\" style=\"color: #57534e; font-size: 0.91rem;\" data-block-key=\"service.do-it-yourself-audiobook.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('do-it-yourself-audiobook', this)\">\n                          *Audiobook distribution partners require that the e-book version is in distribution and available for sale.\n                        </p>\n                      </div>\n                    </div>",
  "professional-audiobook-package": "<div class=\"professional-audiobook-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.professional-audiobook-package.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                          Readers have spoken—and we have listened. These days, they prefer books in a format that will easily fit their busy lifestyle. This is why Omni offers you a solution that allows you to tap into your readers’ multitasking ways: audiobooks. Now they can “read” your book while they commute, work out or even as they do their chores.\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.professional-audiobook-package.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                          But exactly how popular are audiobooks among readers? The growing demand is evidently seen the rise of daily downloads of audiobooks year after year. Tap into that market by having your book available in audio format with our help.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.professional-audiobook-package.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                          The Professional Audiobook service includes:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Audiobook conversion of up to 5,000 words</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Narration by a professional voice-over actor</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Your own digital copy of the audiobook</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Intro, beginning and end background music for your audiobook</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Availability of your audiobook through Overdrive, Audible.com, Amazon.com and iTunes</li>\n                          <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">ISBN Registration</li>\n                        </ul>\n\n                        \n                        <div class=\"audio-samples-card p-4 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <div class=\"mb-4\">\n                            <h5 class=\"fw-bold mb-2 d-flex align-items-center gap-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.professional-audiobook-package.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                              <i class=\"bi bi-volume-up-fill\" style=\"color: #ad7d42;\"></i>\n                              Audiobook Sample: Male\n                            </h5>\n                            <audio controls class=\"w-100\" style=\"max-width: 480px; height: 42px;\">\n                              <source src=\"/assets/audio/Jewel in the Wake_Male.mp3\" type=\"audio/mpeg\" />\n                              Your browser does not support the audio element.\n                            </audio>\n                          </div>\n\n                          <div class=\"mb-2\">\n                            <h5 class=\"fw-bold mb-2 d-flex align-items-center gap-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.professional-audiobook-package.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                              <i class=\"bi bi-volume-up-fill\" style=\"color: #ad7d42;\"></i>\n                              Audiobook Sample: Female\n                            </h5>\n                            <audio controls class=\"w-100\" style=\"max-width: 480px; height: 42px;\">\n                              <source src=\"/assets/audio/Mask Weavers for Hire_Female.mp3\" type=\"audio/mpeg\" />\n                              Your browser does not support the audio element.\n                            </audio>\n                          </div>\n                        </div>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.professional-audiobook-package.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                          The default retail price set will be $9.99 minimum. Please take note that other distributors and resellers have the sole discretion to set the price of the audiobooks they sell.\n                        </p>\n\n                        <div class=\"p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42; padding: 16px 20px;\">\n                          <p class=\"fw-semibold fst-italic mb-2 editable-field\" style=\"color: #ad7d42; font-size: 0.96rem;\" data-block-key=\"service.professional-audiobook-package.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                            Is your book more than 5,000 words?\n                          </p>\n                          <p class=\"fw-semibold fst-italic mb-2 editable-field\" style=\"color: #ad7d42; font-size: 0.96rem;\" data-block-key=\"service.professional-audiobook-package.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                            Need your audiobook converted right away?\n                          </p>\n                          <p class=\"mb-2 editable-field\" style=\"color: #44403c; font-size: 0.93rem; line-height: 1.65;\" data-block-key=\"service.professional-audiobook-package.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">\n                            We can send you your audiobook in 30 days with our Rapid Release Audiobook service for an additional fee of $500. Please take note of the following conditions:\n                          </p>\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-1\" style=\"color: #57534e; font-size: 0.9rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">Your manuscript should only have a maximum of 30,000 words.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.professional-audiobook-package.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('professional-audiobook-package', this)\">You need to approve the audiobook sample we will send you before we can get started on your audiobook. Your 30-day countdown will start from the day we receive your demo approval.</li>\n                          </ul>\n                        </div>\n                      </div>\n                    </div>",
  "softcover-publishing": "<div class=\"softcover-publishing-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.softcover-publishing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                          Softcover Format is already included in select publishing packages and cannot be purchased separately. This page is designed to give you more information about the service and why it’s important for your book.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.softcover-publishing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                          Omni softcover books are formatted as trade paperbacks. Trade paperback is an industry term that describes a book that is of better production quality. These books are produced in a larger size and offered at a higher price than a mass-market paperback format. Mass-market paperbacks are generally cheaply made and printed on newsprint or other low-quality paper, which will discolor and disintegrate over time. Trade paperbacks, on the other hand, meet a higher standard and are printed on high-quality paper.\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.softcover-publishing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                          Omni offers trade paperbacks in the following trim sizes:\n                        </p>\n\n                        <div class=\"row g-4 mb-4\">\n                          <div class=\"col-12 col-md-6\">\n                            <div class=\"p-3.5 rounded-3 h-100\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                              <h5 class=\"fw-bold mb-3 d-flex align-items-center gap-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.softcover-publishing.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                                <i class=\"bi bi-book-half\" style=\"color: #ad7d42;\"></i>\n                                Black & White Trim sizes\n                              </h5>\n                              <ul class=\"mb-0 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">5\" x 8\"</li>\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">5.5\" x 8.5\"</li>\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">6\" x 9\"</li>\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">7.5\" x 9.25\"</li>\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">8.25\" x 11\"</li>\n                              </ul>\n                            </div>\n                          </div>\n                          <div class=\"col-12 col-md-6\">\n                            <div class=\"p-3.5 rounded-3 h-100\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                              <h5 class=\"fw-bold mb-3 d-flex align-items-center gap-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.softcover-publishing.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                                <i class=\"bi bi-palette-fill\" style=\"color: #ad7d42;\"></i>\n                                Color Trim Sizes\n                              </h5>\n                              <ul class=\"mb-0 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">8.5\" x 8.5\"</li>\n                                <li class=\"editable-field\" data-block-key=\"service.softcover-publishing.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">8.5\" x 11\"</li>\n                              </ul>\n                            </div>\n                          </div>\n                        </div>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.softcover-publishing.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                          Omni softcover books are printed on high-quality, acid-free, book-grade opaque paper stock in black and white or grayscale halftones. Softcovers are printed on a bright white cover stock in full color.\n                        </p>\n\n                        <p class=\"fst-italic mb-0 editable-field\" style=\"color: #57534e; font-size: 0.91rem;\" data-block-key=\"service.softcover-publishing.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('softcover-publishing', this)\">\n                          *Books included in publishing packages will be shipped at standard shipping rates.\n                        </p>\n                      </div>\n                    </div>",
  "hardcover-publishing": "<div class=\"hardcover-publishing-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.hardcover-publishing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">\n                          For durability and class, our black & white hardcover publishing is available in your choice of two formats: glossy casebound or dust jacket. The casebound option features a full-color glossy cover image adhered directly to the cover. The dust jacket option features a blue digital cloth cover with a digitally printed non-metallic gold-colored ink onto the spine and a full-color dust jacket with flaps. The full-color dust jacket allows us to print your author biography and a description of your book on the inside flaps, freeing up the back cover to print reviews and endorsements. Your hardcover edition will also be assigned a unique ISBN. In addition to the paperback copies included in your publishing package, you will receive one free author copy of your hardcover edition.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h5 class=\"fw-bold mb-3 d-flex align-items-center gap-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.hardcover-publishing.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">\n                            <i class=\"bi bi-journal-bookmark-fill\" style=\"color: #ad7d42;\"></i>\n                            Black & White Specifications\n                          </h5>\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">Page count range of 108-800</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">\n                              You can choose between these two trim sizes:\n                              <ul class=\"ps-3 mt-1 d-flex flex-column gap-1\">\n                                <li>5.5” × 8.5”</li>\n                                <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">6” × 9”</li>\n                              </ul>\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold fst-italic mb-2\" style=\"color: #ad7d42; font-size: 0.95rem;\">\n                            Please note:\n                          </h6>\n                          <ul class=\"fst-italic mb-0 ps-3 d-flex flex-column gap-1.5\" style=\"color: #57534e; font-size: 0.91rem; line-height: 1.6;\">\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">When publishing a hardcover book, the softcover trim size must match that of the hardcover.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">You can provide additional text for the interior flaps of the case-laminated cover, such as an excerpt of a book review or endorsement.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">During book production, you will be given the opportunity to proof both the softcover and hardcover editions of your cover and suggest changes as appropriate.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">Due to the higher production costs, the retail price for hardcover books may be more than softcover books.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">The delivery time for hardcover book orders is about seven days longer than for softcover books.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li9\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">Author pen name must not exceed 38 characters.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.hardcover-publishing.li10\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">Prices are subject to change without prior notice. Some restrictions may apply.</li>\n                          </ul>\n                        </div>\n\n                        <p class=\"mb-0 fw-medium editable-field\" style=\"color: #2b2219;\" data-block-key=\"service.hardcover-publishing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('hardcover-publishing', this)\">\n                          Your book will be a keepsake for generations to come when you choose to preserve your book in long-lasting hardcover format.\n                        </p>\n                      </div>\n                    </div>",
  "book-binding-sizes-and-types": "<div class=\"book-binding-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.book-binding-sizes-and-types.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                          Please note: These binding and paper options cannot be purchased separately. This page is designed to give you more information about the service and why it’s important for your book.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.book-binding-sizes-and-types.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                          Omni publishes softcover books in perfect-bound format, a type of book binding that uses glue to hold the pages and cover together (typical of most professional books found in stores). We also publish hardcover books in two trim sizes: 5.5\" x 8.5\" or 6\" x 9\". We do not publish wire-o, plasticomb, three-ring, nor spiral-bound books.\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.book-binding-sizes-and-types.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                          The chart below lists the binding and paper options available to you at Omni:\n                        </p>\n\n                        <div class=\"mb-4\">\n                          <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.book-binding-sizes-and-types.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                            Softcover Sizes and Options\n                          </h5>\n                          <div class=\"table-responsive rounded-3 border\" style=\"border-color: #ebd9c4;\">\n                            <table class=\"table table-hover mb-0\" style=\"font-size: 0.92rem;\">\n                              <thead style=\"background: #f8f4ee; color: #2b2219;\">\n                                <tr>\n                                  <th class=\"py-2.5 px-3\">Trim Size</th>\n                                  <th class=\"py-2.5 px-3\">Paper Specifications</th>\n                                  <th class=\"py-2.5 px-3\">Paper Color</th>\n                                </tr>\n                              </thead>\n                              <tbody>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">5\" × 8\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">White or Crème</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">5.5\" × 8.5\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">White or Crème</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">6\" × 9\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">White or Crème</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">7.5\" × 9.25\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">White</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">8.25\" × 11\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">White</td></tr>\n                              </tbody>\n                            </table>\n                          </div>\n                        </div>\n\n                        <div class=\"mb-4\">\n                          <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.book-binding-sizes-and-types.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                            Color Softcover Sizes and Options\n                          </h5>\n                          <div class=\"table-responsive rounded-3 border\" style=\"border-color: #ebd9c4;\">\n                            <table class=\"table table-hover mb-0\" style=\"font-size: 0.92rem;\">\n                              <thead style=\"background: #f8f4ee; color: #2b2219;\">\n                                <tr>\n                                  <th class=\"py-2.5 px-3\">Trim Size</th>\n                                  <th class=\"py-2.5 px-3\">Paper Specifications</th>\n                                  <th class=\"py-2.5 px-3\">Paper Color</th>\n                                </tr>\n                              </thead>\n                              <tbody>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">8.5\" × 8.5\"</td><td class=\"py-2.5 px-3\">70 lb, acid-free</td><td class=\"py-2.5 px-3\">White</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">8.5\" × 11\"</td><td class=\"py-2.5 px-3\">70 lb, acid-free</td><td class=\"py-2.5 px-3\">White</td></tr>\n                              </tbody>\n                            </table>\n                          </div>\n                        </div>\n\n                        <div class=\"mb-3\">\n                          <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.book-binding-sizes-and-types.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('book-binding-sizes-and-types', this)\">\n                            Hardcover Sizes and Options\n                          </h5>\n                          <div class=\"table-responsive rounded-3 border\" style=\"border-color: #ebd9c4;\">\n                            <table class=\"table table-hover mb-0\" style=\"font-size: 0.92rem;\">\n                              <thead style=\"background: #f8f4ee; color: #2b2219;\">\n                                <tr>\n                                  <th class=\"py-2.5 px-3\">Trim Size</th>\n                                  <th class=\"py-2.5 px-3\">Paper Specifications</th>\n                                  <th class=\"py-2.5 px-3\">Paper Color</th>\n                                </tr>\n                              </thead>\n                              <tbody>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">5.5\" × 8.5\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">Crème</td></tr>\n                                <tr><td class=\"py-2.5 px-3 fw-medium\">6\" × 9\"</td><td class=\"py-2.5 px-3\">50 lb, acid-free, lignin-free</td><td class=\"py-2.5 px-3\">Crème</td></tr>\n                              </tbody>\n                            </table>\n                          </div>\n                        </div>\n                      </div>\n                    </div>",
  "black-and-white-illustrations-fine-detail": "<div class=\"illustration-fine-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">\n                          Introduce a new level of artistry to your book by including beautiful black-and-white imagery that will enhance your readers’ experience of your book. With Omni's Fine Detail line of custom black-and-white illustrations, basic highlights and shadows will be added to illustrated objects and sceneries to add a greater level of depth and dimension. Our talented team of in-house studio artists will use your ideas and creative direction to produce images that can help strengthen both your book’s message and marketability.\n                        </p>\n                        \n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.black-and-white-illustrations-fine-detail.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">\n                          Your black-and-white illustrations can be produced in the following styles:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">Juvenile/Whimsical (a sweet, cute style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">Cartoon/Humor (a humorous, funny style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">Fantasy (a comic-book or mythical style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">Science Fiction (a futuristic or technological style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">Naturalistic (a true-to-life style)</li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.link_info\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\">\n                          <a href=\"/services?service=black-and-white-illustrations-fine-detail\" class=\"service-inline-link fw-semibold\">See samples of Fine Detail black-and-white illustrations in the Custom Illustrations Information Center »</a>\n                        </p>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/illustration.jpg\" alt=\"Fine Detail Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" data-block-key=\"service.black-and-white-illustrations-fine-detail.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-fine-detail', this)\" style=\"color: #57534e; font-size: 0.95rem; line-height: 1.65;\">\n                            Take your book to the next level with Fine Detail black-and-white illustrations. The typical timeline for this service is six to 12 weeks depending on our work queue and the complexity of your project.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "black-and-white-illustrations-personalized": "<div class=\"illustration-personalized-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">\n                          You already did the impressive work of writing a book. Now let Omni help you enhance it with custom black-and-white illustrations. Our talented artists will use your ideas and creative direction to create unique illustrations that will fit perfectly with your book. The clean lines and uniform shading used in creating Personalized illustrations are perfect for a simple, classic look. These black-and-white illustrations can be created in a wide variety of styles and subject matter, from people and landscapes to technical drawings and maps.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.black-and-white-illustrations-personalized.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">\n                          Your black-and-white illustrations can be produced in the following styles:\n                        </h5>\n                        <ul class=\"mb-3 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">Juvenile/Whimsical (a sweet, cute style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">Cartoon/Humor (a humorous, funny style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">Fantasy (a comic-book or mythical style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">Science Fiction (a futuristic or technological style)</li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.link_info\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">\n                          <a href=\"/services?service=black-and-white-illustrations-fine-detail\" class=\"service-inline-link fw-semibold\">See samples of Fine Detail black-and-white illustrations in the Custom Illustrations Information Center »</a>\n                        </p>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/illustration.jpg\" alt=\"Personalized Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\">\n                          Our artists can also create illustrations in a realistic style; however, you'll need to select our Fine Detail illustration service.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" data-block-key=\"service.black-and-white-illustrations-personalized.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('black-and-white-illustrations-personalized', this)\" style=\"color: #57534e; font-size: 0.95rem; line-height: 1.65;\">\n                            Add a classic look to your book with these custom black-and-white illustrations. The typical timeline for this service is six to 12 weeks depending on our work queue and the complexity of your project.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "color-illustrations-intricate-design": "<div class=\"color-illustrations-intricate-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-intricate-design.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">\n                          Intricate Design color illustrations are created by hand and still consist of defining outlines but with varying degrees of line details. By giving greater levels of shading and highlights within the line art, the artist creates more three-dimensional illustrations. This is the only level where the art can be colored digitally or by hand.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-intricate-design.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">\n                          By adding details and textures and varying color values, your illustrator will add a high level of 3-dimensionality to your color illustrations. Omni's in-house studio artists will use your ideas and description of your characters and storyline to create unique artwork that is appropriate your book and its target audience.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.color-illustrations-intricate-design.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">\n                          Your full-color illustrations can be produced in the following styles:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-intricate-design.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">Juvenile/Whimsical (a sweet, cute style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-intricate-design.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">Cartoon/Humor (a humorous, funny style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-intricate-design.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">Fantasy (a comic-book or mythical style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-intricate-design.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">Science Fiction (a futuristic or technological style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-intricate-design.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">Naturalistic (a true-to-life style)</li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-intricate-design.link_info\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">\n                          <a href=\"/services?service=black-and-white-illustrations-fine-detail\" class=\"service-inline-link fw-semibold\" style=\"color: #ad7d42; font-style: italic;\">See samples of Fine Detail black-and-white illustrations in the Custom Illustrations Information Center »</a>\n                        </p>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/colored.jpg\" alt=\"Intricate Color Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #ad7d42; font-size: 1.1rem;\" data-block-key=\"service.color-illustrations-intricate-design.h5_more\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">\n                          More About | Color Illustrations – Intricate Design\n                        </h5>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-intricate-design.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-intricate-design', this)\">\n                          Captivate your readers with breathtaking, full-color illustrations that fill the pages of your book. The typical timeline for this service is six to 12 weeks depending on our work queue and the complexity of your project.\n                        </p>\n                      </div>\n                    </div>",
  "color-illustrations-fine-detail": "<div class=\"color-illustrations-fine-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-fine-detail.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">\n                          Enhance your readers' experience with detailed and vibrant illustrations. The Fine Detail illustrations created for your book will be drawn by hand and colored digitally. At this level of artistry, your Omni illustrator will add basic shadows and highlights to objects and scenery, giving your book’s artwork a greater level of depth and dimension.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.color-illustrations-fine-detail.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">\n                          Your full-color illustrations can be produced in the following styles:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-fine-detail.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">Juvenile/Whimsical (a sweet, cute style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-fine-detail.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">Cartoon/Humor (a humorous, funny style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-fine-detail.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">Fantasy (a comic-book or mythical style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-fine-detail.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">Science Fiction (a futuristic or technological style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-fine-detail.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">Naturalistic (a true-to-life style)</li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-fine-detail.link_info\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">\n                          <a href=\"/services?service=color-illustrations-fine-detail\" class=\"service-inline-link fw-semibold\" style=\"color: #ad7d42; font-style: italic;\">See samples of Fine Detail color illustrations in the Illustrations Information Center »</a>\n                        </p>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/colored.jpg\" alt=\"Fine Detail Color Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #ad7d42; font-size: 1.1rem;\" data-block-key=\"service.color-illustrations-fine-detail.h5_more\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">\n                          More About | Color Illustrations – Fine Detail\n                        </h5>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-fine-detail.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">\n                          Your Fine Detail color illustrations will add an extra layer of visual interest and professionalism to your book. The typical timeline for this service is six to 12 weeks depending on our work queue and the complexity of your project.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Timeline: </span>\n                          <span style=\"color: #57534e;\">Six to 12 weeks depending on work queue and project complexity</span>\n                        </div>\n\n                        <p class=\"fst-italic text-muted mt-4 pt-3 border-top editable-field\" style=\"font-size: 0.82rem; line-height: 1.6;\" data-block-key=\"service.color-illustrations-fine-detail.disclaimer\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-fine-detail', this)\">\n                          Disclaimer: Prices listed do not include applicable taxes (such as sales, use, excise, value-added, goods and services, or other tax), which will be added to the total at the time of purchase. Prices listed do include the copies of the book; the cost of shipping and handling will be calculated and charged after your book is made available for sale.\n                        </p>\n                      </div>\n                    </div>",
  "color-illustrations-personalized": "<div class=\"color-illustrations-personalized-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-personalized.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">\n                          Elevate your book to the next creative level with artwork produced by our talented illustration team. Omni's in-house studio artists will follow your ideas and direction to produce striking artwork that accentuates your carefully crafted book.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-personalized.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">\n                          With Personalized illustrations, art is drawn by hand and colored digitally. The clean lines and uniform colors create a simple style that will add a classic look to your book. These full-color illustrations can be created in a wide variety of styles and subject matter, from people and landscapes to technical drawings and maps.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.color-illustrations-personalized.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">\n                          Your full-color illustrations can be produced in the following styles:\n                        </h5>\n                        <ul class=\"mb-3 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-personalized.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">Juvenile/Whimsical (a sweet, cute style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-personalized.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">Cartoon/Humor (a humorous, funny style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-personalized.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">Fantasy (a comic-book or mythical style)</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-illustrations-personalized.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">Science Fiction (a futuristic or technological style)</li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-personalized.link_info\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">\n                          <a href=\"/services?service=black-and-white-illustrations-fine-detail\" class=\"service-inline-link fw-semibold\" style=\"color: #ad7d42; font-style: italic;\">See samples of Fine Detail black-and-white illustrations in the Custom Illustrations Information Center »</a>\n                        </p>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/colored.jpg\" alt=\"Personalized Color Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n\n                        <p class=\"fst-italic mb-3 editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.color-illustrations-personalized.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">\n                          Our artists can also create illustrations in a more realistic style; however, you'll need to select our Fine Detail or Intricate Design illustrations.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #ad7d42; font-size: 1.1rem;\" data-block-key=\"service.color-illustrations-personalized.h5_more\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">\n                          More About | Color Illustrations – Personalized\n                        </h5>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-illustrations-personalized.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-illustrations-personalized', this)\">\n                          The visual interest your custom color illustrations add to your book will make for a more enjoyable and immersive experience for your readers. The typical timeline for this service is six to 12 weeks depending on our work queue and the complexity of your project.\n                        </p>\n                      </div>\n                    </div>",
  "elite-cover-design": "<div class=\"elite-cover-design-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.elite-cover-design.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">\n                          Please Note: Elite Cover Design is included in select publishing packages and cannot be purchased separately. This page is designed to give you more information about the service and why it is important for your book.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.elite-cover-design.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">\n                          A potential reader’s decision to learn more about your book is often determined by the appeal of your book’s cover. Although we’ve all been told to “never judge a book by its cover,” it’s hard not to let a book’s visual appearance sway our judgment when there are so many books to choose from. One of the primary ways to entice readers to discover and purchase your book over thousands of other books is by capturing their interest with a compelling cover design.\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.elite-cover-design.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">\n                          With Omni’s Elite Cover Design, you will work one-on-one with a professional cover designer who will be committed to creating a cover that compliments your written work and gives your book its best shot at success in today’s competitive market.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.elite-cover-design.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">\n                          The Elite Difference:\n                        </h5>\n                        <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.elite-cover-design.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">Your Omni cover designer will conduct creative research on genre-specific cover trends to determine which design will maximize your book's impact in the marketplace.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-cover-design.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">Your designer will propose three front cover concepts that reflect the feel of your book.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-cover-design.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">Once you choose your favorite concept, you and your designer will confirm the details about the design elements.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-cover-design.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">You will receive the first draft of the cover and have one free round of corrections.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.elite-cover-design.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-cover-design', this)\">After your designer incorporates any changes per your request to your design, you’ll receive your final cover as a PDF (Please note: any changes requested after the initial round of free corrections will incur a fee).</li>\n                        </ul>\n                      </div>\n                    </div>",
  "custom-cover-illustration": "<div class=\"custom-cover-illustration-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.custom-cover-illustration.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">\n                          If you want your idea translated into an original piece of art, you've come to the right place. Our team of experienced in-house artists will work with you to produce a striking custom cover illustration that will help your book stand out.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.custom-cover-illustration.h5_heading1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">\n                            How Does a Custom Cover Illustration Benefit You and Your Book?\n                          </h5>\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">People really do judge a book by its cover—first and foremost, the purpose of your book cover is to make people pick up your book, or click on the virtual version.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">The artwork created is unique to your book, which both readers and booksellers will notice.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">Artwork can be created in a variety of mediums depending on what you think will enhance your book.</li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.custom-cover-illustration.h5_heading2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">\n                            How Does the Process Work?\n                          </h5>\n                          <ol class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">You’ll connect with our art team to discuss the initial book cover concept and timelines.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">They’ll create a sketch from your instructions and work with you through two free rounds of revisions if necessary to create a final illustration to your specifications.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.custom-cover-illustration.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">You’ll work with our design team to create a finished book cover using the final artwork.</li>\n                          </ol>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h5 class=\"fw-bold mb-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.custom-cover-illustration.h5_heading3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">\n                            More About | Custom Cover Illustration\n                          </h5>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.95rem; line-height: 1.65;\" data-block-key=\"service.custom-cover-illustration.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-cover-illustration', this)\">\n                            Illustrations usually take <strong>6 to 12 weeks</strong> to complete depending on our work queue and the complexity of your project.\n                          </p>\n                        </div>\n\n                        <div class=\"text-center my-4\">\n                          <img src=\"/assets/img/colored.jpg\" alt=\"Cover Illustration Sample\" class=\"img-fluid rounded-3 shadow-sm\" style=\"max-height: 380px;\" />\n                        </div>\n                      </div>\n                    </div>",
  "cover-revisions-text": "<div class=\"cover-revisions-text-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.cover-revisions-text.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">\n                          Cover Revisions (Text) are corrections that are made to the text on the cover layout. During your publication process, you are given one round of revisions to the cover at no charge. If after this initial round of edits you would like some additional modifications, this design service enables you to make text changes to your cover for a fee.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.cover-revisions-text.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">\n                          Text adjustments range from:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-text.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">replacing a few words</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-text.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">correcting punctuation</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-text.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">adding additional quotes and other information</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-text.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">completely replacing sections of cover text</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.65;\" data-block-key=\"service.cover-revisions-text.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-text', this)\">\n                            It is the author's responsibility to supply Omni with the exact changes, location, and phrases that they would like to change or replace. It is also the responsibility of the author to proofread or edit these changes.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "cover-revisions-images-design": "<div class=\"cover-revisions-images-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.cover-revisions-images-design.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">\n                          Cover Revisions (Images/Design) are changes to imagery and design elements on the cover layout that are NOT text changes. The following services are just a few of many that Omni can complete for an author:\n                        </p>\n\n                        <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Touch-up photographs</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Blend several images together</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Remove components of an image</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Combine elements from several different images into one scene</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Changing/manipulating skin color, eye color, scene color</li>\n                          <li class=\"editable-field\" data-block-key=\"service.cover-revisions-images-design.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('cover-revisions-images-design', this)\">Red-eye reduction</li>\n                        </ul>\n                      </div>\n                    </div>",
  "elite-interior-design": "<div class=\"elite-interior-design-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.elite-interior-design.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                          Please Note: Elite Interior Design is included in select publishing packages and cannot be purchased separately. This page is designed to give you more information about the service and why it’s important for your book.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.elite-interior-design.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                          With Elite Interior Design, you will hold a one-on-one consultation with an Omni book layout specialist who has special training in designing for your book’s genre. Using your ideas and input, your designer will create the interior page layout your book needs.\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.elite-interior-design.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                          This interior will include chapter titles, headings, page numbers and other layout details that will allow for easy reading and ensure your book meets industry standards. The layout designer will also insert photos or graphics and conduct minimal manuscript cleanup.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.elite-interior-design.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                            Here’s how it works:\n                          </h5>\n                          <ul class=\"mb-0 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Your Omni designer will conduct creative research on genre-specific book layout trends to determine which design will maximize your book's impact in the marketplace.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Your designer will discuss concepts that reflect the feel of your book (such as fonts, chapter starts, title page design, etc.).</li>\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Your designer will then create three mock-ups of the front matter, including the first few pages of the first chapter.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Once you choose your favorite concept, we will confirm the details about the design elements.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">You will receive the first draft of the completed layout as a PDF and have one round of 50 free corrections.</li>\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">After your designer incorporates any changes, you’ll receive your final galley as a PDF (Please Note: Any changes requested after the initial round of free corrections will incur a fee).</li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2 editable-field\" style=\"color: #2b2219; font-size: 1.02rem;\" data-block-key=\"service.elite-interior-design.h6_guidance\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                            Margin Guidance:\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.93rem; line-height: 1.68;\" data-block-key=\"service.elite-interior-design.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                            During this process, the designer will change your manuscript’s margins to fit your chosen book size. We strongly recommend changing the margins yourself so you can see how the text will look in your book’s final dimensions. This will help you catch any formatting errors caused by text shifts or line breaks that might otherwise result in a delay in your book’s production.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2 editable-field\" style=\"color: #2b2219; font-size: 1.02rem;\" data-block-key=\"service.elite-interior-design.h6_requirements\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                            Image and Non-Text Submission Requirements:\n                          </h6>\n                          <ul class=\"mb-2 ps-3 d-flex flex-column gap-2\" style=\"color: #57534e; font-size: 0.93rem;\">\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Submitted separately from your manuscript as a TIFF (.tif) file format</li>\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li8\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">CMYK colorspace</li>\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li9\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">300-dpi resolution</li>\n                            <li class=\"editable-field\" data-block-key=\"service.elite-interior-design.li10\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">Written copyright permission from the creator (artist, photographer, etc.) to use the work in your book</li>\n                          </ul>\n                          <p class=\"fst-italic mb-0 editable-field\" style=\"color: #78716c; font-size: 0.88rem;\" data-block-key=\"service.elite-interior-design.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('elite-interior-design', this)\">\n                            Exception: Sample graphics and other illustrations used only as ideas or guidelines for the design team can be submitted in any format.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "color-image-insertion": "<div class=\"color-image-insertion-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-image-insertion.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">\n                          If you want to insert additional graphics beyond the allotted number of image insertions of your chosen package, follow the guidelines below. Note that images refer to color photos, tables, charts, diagrams, etc.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.color-image-insertion.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">\n                          Submission Guidelines for Inserting Color Graphics into the Interior of Your Book:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.color-image-insertion.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">All interior color graphics (including photos, tables, charts, diagrams, drawings, foreign fonts, and anything else that is not text or would be considered a graphic) should be submitted as individual TIFF (.tif) files.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-image-insertion.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">The manuscript should identify placeholders for each of the interior graphics.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-image-insertion.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">There is a fee for each additional image inserted into the manuscript.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-image-insertion.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">The book cover does not \"count\" as a graphic. It is in full color for no additional charge.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.color-image-insertion.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-insertion', this)\">Printer slang for \"full color\" is \"four color\"; this means the full range of colors, not literally just four colors.</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                          <span style=\"color: #57534e;\">During design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "custom-layout-tech": "<div class=\"custom-layout-tech-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.custom-layout-tech.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-layout-tech', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.custom-layout-tech.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-layout-tech', this)\">\n                          Certain books may require a specialized layout technician to work with you on your specific custom layout requirements.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration & Cost: </span>\n                          <span style=\"color: #57534e;\">Dependent on complexity</span>\n                        </div>\n                      </div>\n                    </div>",
  "table-of-contents-two-or-more": "<div class=\"toc-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.table-of-contents-two-or-more.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('table-of-contents-two-or-more', this)\">\n                          Please speak to your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.table-of-contents-two-or-more.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('table-of-contents-two-or-more', this)\">\n                          Creating a table of contents for your work will demonstrate to your reader how the information has been organized. In order to better organize your work, multiple tables of contents might be necessary. After the first free table of contents, Omni can create your additional tables of contents with this service.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                          <span style=\"color: #57534e;\">Dependent on quantity and complexity</span>\n                        </div>\n                      </div>\n                    </div>",
  "table-creation": "<div class=\"table-creation-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.table-creation.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('table-creation', this)\">\n                          Please do not order without first speaking with your publishing services associate.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.table-creation.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('table-creation', this)\">\n                          Our designers can create and format professional tables to be inserted into your manuscript as needed.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration & Cost: </span>\n                          <span style=\"color: #57534e;\">Dependent on quantity and complexity</span>\n                        </div>\n                      </div>\n                    </div>",
  "footnote-formatting": "<div class=\"footnote-formatting-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.footnote-formatting.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('footnote-formatting', this)\">\n                          Adding footnotes to your manuscript can be very useful. Omni follows the Chicago Manual of Style citation guidelines when inserting footnotes for you. Most often, footnotes are used as a replacement for long, explanatory notes. They can also be used for other various reasons:\n                        </p>\n\n                        <ul class=\"mb-3 ps-3 d-flex flex-column gap-1.5\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.footnote-formatting.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('footnote-formatting', this)\">To direct the reader to more information pertaining to the subject in the main text;</li>\n                          <li class=\"editable-field\" data-block-key=\"service.footnote-formatting.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('footnote-formatting', this)\">To reference a quote or viewpoint; or</li>\n                          <li class=\"editable-field\" data-block-key=\"service.footnote-formatting.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('footnote-formatting', this)\">To use as an alternative to parenthetical references.</li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" style=\"font-size: 0.93rem; line-height: 1.68;\" data-block-key=\"service.footnote-formatting.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('footnote-formatting', this)\">\n                          Footnotes are indicated by a superscript number that corresponds to a note at the bottom of the page that is written in a smaller font and labeled with the same number. It also includes the citation number in superscript and contains the full citation the first time the source is cited. Every subsequent citation of the source only requires an abbreviated citation. The first line of all footnotes is indented, single spaced, and without extra space between references.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                          <span style=\"color: #57534e;\">During design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "custom-headers": "<div class=\"custom-headers-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.custom-headers.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('custom-headers', this)\">\n                          You may find it important to create custom headers within your book. If at any time during the submission process you would like to change a header within your work, you simply need to purchase our Custom Header service.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                          <span style=\"color: #57534e;\">During design process</span>\n                        </div>\n                      </div>\n                    </div>",
  "b-w-image-insertion": "<div class=\"bw-image-insertion-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.b-w-image-insertion.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">\n                          If you want to insert additional graphics beyond the allotted number of image insertions of your chosen package, follow the guidelines below. Note that images refer to photos, tables, charts, diagrams, etc.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.b-w-image-insertion.h5_heading\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">\n                          Submission Guidelines for Inserting Graphics into the Interior of Your Book:\n                        </h5>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">All interior graphics (including photos, tables, charts, diagrams, drawings, foreign fonts, and anything else that is not text or would be considered a graphic) should be submitted as individual TIFF (.tif) files.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">The manuscript should identify placeholders for each of the interior graphics.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">There is a fee per additional image inserted into the manuscript.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">All illustrations are produced in black and white or grayscale; we cannot process color inside the manuscript.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">The book cover does not \"count\" as a graphic. It is in full color for no additional charge.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.b-w-image-insertion.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">Printer slang for \"full color\" is \"four color\"; this means the full range of colors, not literally just four colors.</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <div class=\"mb-2\">\n                            <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                            <span style=\"color: #57534e;\">During design process</span>\n                          </div>\n                          <p class=\"fst-italic mb-2 editable-field\" style=\"color: #78716c; font-size: 0.86rem; line-height: 1.6;\" data-block-key=\"service.b-w-image-insertion.disclaimer1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">\n                            Disclaimer: Prices listed do not include applicable taxes (such as sales, use, excise, value-added, goods and services, or other tax), which will be added to the total at the time of purchase.\n                          </p>\n                          <p class=\"fst-italic mb-0 editable-field\" style=\"color: #78716c; font-size: 0.86rem; line-height: 1.6;\" data-block-key=\"service.b-w-image-insertion.disclaimer2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-insertion', this)\">\n                            Prices listed do include the copies of the book; the cost of shipping and handling will be calculated and charged after your book is made available for sale.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "interior-revisions-block-of-25": "<div class=\"interior-revisions-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.interior-revisions-block-of-25.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('interior-revisions-block-of-25', this)\">\n                          Omni gives you one opportunity to examine your book proofs and make up to 50 corrections for free. It is imperative that you list these corrections on the proof form provided in order for the changes to be made. Publisher errors such as hyphenation errors, formatting issues or misplaced graphics which occurred during production must also be noted on the proof from, but will not count against the first free 50 corrections.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.interior-revisions-block-of-25.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('interior-revisions-block-of-25', this)\">\n                          Remember to carefully review each page of your proofs for any formatting or typographical errors that were created by either you or Omni. Our proofing process is designed to give you the final say about your book’s appearance by allowing you to rectify any remaining problems or errors.\n                        </p>\n                        <p class=\"mb-3 editable-field\" style=\"color: #57534e; font-size: 0.94rem;\" data-block-key=\"service.interior-revisions-block-of-25.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('interior-revisions-block-of-25', this)\">\n                          If you wish to make further proofreading corrections after the initial free 50, there is a charge for every group of 25 changes.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <span class=\"fw-bold\" style=\"color: #ad7d42;\">Duration: </span>\n                          <span style=\"color: #57534e;\">7-10 Business days</span>\n                        </div>\n                      </div>\n                    </div>",
  "stock-image-processing": "<div class=\"stock-image-processing-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.stock-image-processing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('stock-image-processing', this)\">\n                          All books published via the Omni standard publishing packages receive custom-designed covers, produced in full color. Within the realm of this custom-designed cover, you have the option to choose two images, free of charge, from the millions found through Getty Images. If you wish to include more than two images on your cover, a Stock Image Processing fee will be assessed. This fee will also be placed on any images found through Getty Images you wish to use in the interior of your book.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.stock-image-processing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('stock-image-processing', this)\">\n                          or speak to an Omni team member for more information about this service Disclaimer: Prices listed do not include applicable taxes (such as sales, use, excise, value-added, goods and services, or other tax), which will be added to the total at the time of purchase. Prices listed do include the copies of the book; the cost of shipping and handling will be calculated and charged after your book is made available for sale.\n                        </p>\n                        <p class=\"mb-0 editable-field\" data-block-key=\"service.stock-image-processing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('stock-image-processing', this)\">\n                          To avoid these fees please adhere to the manuscript submission guidelines.\n                        </p>\n                      </div>\n                    </div>",
  "retech": "<div class=\"retech-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.retech.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retech', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.retech.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retech', this)\">\n                          Once you have received your first interior proof from your design team, it is possible that the number of errors (usually more than 100 corrections) is such that it's in your best interest to supply us with a revised manuscript to reformat into a new interior proof for you to review. If the retech service is done at your request, there is an initial charge for the retech service and any applicable special formatting fees will need to be paid again (indexing, tables, etc.). Please contact your Publishing Services Associate for a complete quote.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.retech.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retech', this)\">\n                          In addition to providing a new manuscript, you will also have another opportunity to re-select your book’s trim size and provide revised formatting suggestions to your Publishing Services Associate. This includes changes of typeface, type size, image treatments, and the overall style in which your book was formatted. It is important that you express these types of formatting requests to your Publishing Services Associate, or supply an interior proof form, along with your newly revised manuscript. If we do not receive revised formatting requests, then the design team will utilize the same styling as the first proof you received from us.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219;\">\n                            Resubmission Discount:\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.retech.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retech', this)\">\n                            Please Note: If you are resubmitting to do a retech then the price of the retech is reduced when purchased with the resubmission.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3.5 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-1\" style=\"color: #2b2219;\">\n                            More About | Retech\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.retech.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('retech', this)\">\n                            If additional revisions are needed, this is the perfect opportunity to make your book shine.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "title-change-after-setup": "<div class=\"title-change-after-setup-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.title-change-after-setup.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('title-change-after-setup', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-0 editable-field\" data-block-key=\"service.title-change-after-setup.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('title-change-after-setup', this)\">\n                          If an author wants to make changes to the title it impacts many elements within the book and through the registration and marketing of the book.\n                        </p>\n                      </div>\n                    </div>",
  "color-image-scanning": "<div class=\"color-image-scanning-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.color-image-scanning.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-scanning', this)\">\n                          Authors who send in hard copies of original color images can have them scanned and placed into the correct place in your work.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.color-image-scanning.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-scanning', this)\">\n                          Omni allows usage of original color art to be placed within a manuscript. Authors who send in hard copies may purchase the Color Image Scanning service. Omni will take the original image and scan it into the correct place in your work.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.color-image-scanning.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('color-image-scanning', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1-2 Weeks dependent on quantity\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "basic-manuscript-formatting-corrections": "<div class=\"basic-manuscript-formatting-corrections-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.basic-manuscript-formatting-corrections.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.basic-manuscript-formatting-corrections.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">\n                          We often receive manuscripts that require formatting corrections before we can start the editorial and layout processes. These include:\n                        </p>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #57534e; font-size: 0.94rem; line-height: 1.8;\">\n                          <li class=\"editable-field\" data-block-key=\"service.basic-manuscript-formatting-corrections.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">Removing headers, footers, page numbering, etc.</li>\n                          <li class=\"editable-field\" data-block-key=\"service.basic-manuscript-formatting-corrections.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">Inserting page breaks appropriately</li>\n                          <li class=\"editable-field\" data-block-key=\"service.basic-manuscript-formatting-corrections.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">Correcting soft and hard returns</li>\n                          <li class=\"editable-field\" data-block-key=\"service.basic-manuscript-formatting-corrections.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">Correcting line and paragraph formatting</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.basic-manuscript-formatting-corrections.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('basic-manuscript-formatting-corrections', this)\">\n                            <strong style=\"color: #2b2219;\">Submission Tip:</strong> To avoid these fees please adhere to the manuscript submission guidelines.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "extensive-customized-formatting": "<div class=\"extensive-customized-formatting-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.extensive-customized-formatting.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.extensive-customized-formatting.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">\n                          Occasionally we receive manuscripts that require an extensive amount of formatting before we can start the editorial and layout process.\n                        </p>\n\n                        <p class=\"fw-semibold mb-2 editable-field\" style=\"color: #2b2219; font-size: 0.95rem;\" data-block-key=\"service.extensive-customized-formatting.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">\n                          This includes:\n                        </p>\n                        <ul class=\"mb-4 ps-3\" style=\"color: #57534e; font-size: 0.94rem; line-height: 1.8;\">\n                          <li class=\"editable-field\" data-block-key=\"service.extensive-customized-formatting.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">Removing text boxes</li>\n                          <li class=\"editable-field\" data-block-key=\"service.extensive-customized-formatting.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">Removing embedded graphics</li>\n                          <li class=\"editable-field\" data-block-key=\"service.extensive-customized-formatting.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">Removing wrapped text, etc.</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.extensive-customized-formatting.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">\n                            <strong style=\"color: #2b2219;\">Submission Tip:</strong> To avoid these fees please adhere to the manuscript submission guidelines.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.extensive-customized-formatting.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('extensive-customized-formatting', this)\">\n                            <strong style=\"color: #2b2219;\">Duration & Scope:</strong> Duration and cost are dependent on quantity and complexity.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "data-entry-standard": "<div class=\"data-entry-standard-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.data-entry-standard.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-standard', this)\">\n                          At Omni we can take your printed manuscript and convert it into a working digital file. Our professional staff can then work on your manuscript more efficiently. Because we are a print-on-demand publishing company, we must have a digital file available.\n                        </p>\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.data-entry-standard.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-standard', this)\">\n                          The Standard Data Entry converts documents that have been typed. This excludes any handwritten documents or newspaper-type articles.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <strong style=\"color: #2b2219;\">Duration:</strong> <span class=\"editable-field\" data-block-key=\"service.data-entry-standard.duration\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-standard', this)\" style=\"color: #57534e;\">45-60 Days</span>\n                        </div>\n                      </div>\n                    </div>",
  "data-entry-spanish": "<div class=\"data-entry-spanish-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.data-entry-spanish.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-spanish', this)\">\n                          Spanish-language materials you provide are converted into an electronic format for publication with our Spanish Data Entry service.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.data-entry-spanish.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-spanish', this)\">\n                          In order for our professional staff to efficiently work on your manuscript, Omni must have a digital file to manipulate. The Data Entry - Spanish service will convert typed Spanish-language material that you have provided into an electronic format for publication.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.data-entry-spanish.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-spanish', this)\">\n                            <strong style=\"color: #2b2219;\">Notice:</strong> This excludes any handwritten documents or newspaper-type articles.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.data-entry-spanish.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-spanish', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 60-75 days\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "data-entry-handwritten": "<div class=\"data-entry-handwritten-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.data-entry-handwritten.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-handwritten', this)\">\n                          Relieve yourself from the tedious task of encoding multiple pages and let us do all the manual encoding for you. This service is only applicable to handwritten documents.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.data-entry-handwritten.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-handwritten', this)\">\n                          Is your manuscript handwritten? Now you have the option to have your book converted into a digital file. In order for our professional staff to efficiently work on your manuscript, Omni must have a digital file to manipulate. Leave it to the Omni team of professionals to manually type and convert your document.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.data-entry-handwritten.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('data-entry-handwritten', this)\">\n                            <strong style=\"color: #2b2219;\">Service Note:</strong> This service will only be applied to handwritten documents.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "large-image-scanning": "<div class=\"large-image-scanning-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.large-image-scanning.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('large-image-scanning', this)\">\n                          Please contact your publishing services consultant for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.large-image-scanning.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('large-image-scanning', this)\">\n                          The Large Image Scanning services include images that are larger than 11\" x 17\". Omni will professionally scan your oversized artwork and visuals to ensure crystal clarity when printed in your book.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.large-image-scanning.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('large-image-scanning', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 2-3 weeks\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "b-w-image-scanning": "<div class=\"b-w-image-scanning-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.b-w-image-scanning.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-scanning', this)\">\n                          Authors who send in hard copies of original black and white images can have them scanned and placed into the correct place in your work.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.b-w-image-scanning.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-scanning', this)\">\n                          Omni allows usage of original black and white art to be placed within a manuscript. Authors who send in hard copies may purchase the Black and White Image Scanning service. Omni will take the original image and scan it into the correct place in your work.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.b-w-image-scanning.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('b-w-image-scanning', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1-2 Weeks dependent on quantity\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "manuscript-file-conversion": "<div class=\"manuscript-file-conversion-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.manuscript-file-conversion.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('manuscript-file-conversion', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.manuscript-file-conversion.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('manuscript-file-conversion', this)\">\n                          Omni will make every effort to work with manuscripts created using a wide variety of software packages. We will charge a small conversion fee for documents created under such formats as WordPerfect, WordPad, and Microsoft Works.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.manuscript-file-conversion.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('manuscript-file-conversion', this)\">\n                            <strong style=\"color: #2b2219;\">Submission Tip:</strong> To avoid these fees please adhere to the manuscript submission guidelines.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.manuscript-file-conversion.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('manuscript-file-conversion', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1 week\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "graphic-file-conversions-quantity-25": "<div class=\"graphic-file-conversions-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.graphic-file-conversions-quantity-25.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.graphic-file-conversions-quantity-25.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">\n                          Authors often send in graphic files (these include graphics, tables, text boxes) that require an extensive amount of work. These include:\n                        </p>\n\n                        <ul class=\"mb-3 ps-3\" style=\"color: #57534e; font-size: 0.94rem; line-height: 1.8;\">\n                          <li class=\"editable-field\" data-block-key=\"service.graphic-file-conversions-quantity-25.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">Cropping graphics as requested by the author</li>\n                          <li class=\"editable-field\" data-block-key=\"service.graphic-file-conversions-quantity-25.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">Extracting graphics from the manuscript</li>\n                          <li class=\"editable-field\" data-block-key=\"service.graphic-file-conversions-quantity-25.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">Converting line art to TIFF (.tif) files</li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" style=\"color: #44403c; font-size: 0.95rem;\" data-block-key=\"service.graphic-file-conversions-quantity-25.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">\n                          Your graphic files will be reviewed and a price quoted based on a price per block of 25 graphic files. The author will have the option of making the changes themselves or paying for Omni staff to make the changes.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.graphic-file-conversions-quantity-25.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">\n                            <strong style=\"color: #2b2219;\">Submission Tip:</strong> To avoid these fees please adhere to the image submission guidelines.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.graphic-file-conversions-quantity-25.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('graphic-file-conversions-quantity-25', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1-2 weeks\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "file-merging": "<div class=\"file-merging-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.file-merging.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('file-merging', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.file-merging.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('file-merging', this)\">\n                          The standard manuscript submission process is based around Omni receiving the manuscript as one file. Some authors may choose to send their manuscript to Omni in several files. The File Merging service is used to merge these files into one document for both editorial services and layout.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.file-merging.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('file-merging', this)\">\n                            <strong style=\"color: #2b2219;\">Submission Tip:</strong> To avoid these fees please adhere to the manuscript submission guidelines.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.file-merging.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('file-merging', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1 week\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "image-extraction": "<div class=\"image-extraction-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.image-extraction.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('image-extraction', this)\">\n                          Please speak with your publishing services associate for more information.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.image-extraction.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('image-extraction', this)\">\n                          If you choose to submit your manuscript with the images included in the body of your work, Omni must extract these images to properly create a professional layout of your book. The images will be placed back into the manuscript once the layout is complete.\n                        </p>\n\n                        <div class=\"p-3 mb-3 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.image-extraction.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('image-extraction', this)\">\n                            <strong style=\"color: #2b2219;\">Interior Layout Protection:</strong> This service will cover the cost of extracting the images to ensure proper interior layout.\n                          </p>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.68;\" data-block-key=\"service.image-extraction.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('image-extraction', this)\">\n                            <strong style=\"color: #2b2219;\">Duration:</strong> 1-2 weeks\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "resubmission-one-version": "<div class=\"resubmission-one-version-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.resubmission-one-version.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">\n                          When a book has gone live and the author finds problems, errors, or other issues that need to be corrected, we can re-submit the file to the printer to update future copies.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.resubmission-one-version.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">\n                          Note: If the author is resubmitting to do a re-tech, then the price of the re-tech is reduced from $275 to $250 when purchased with the resubmission.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.resubmission-one-version.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">\n                          Please remember that the title and the price (Omni bookstore or retail) for a book going through resubmission cannot be changed after it has gone live.\n                        </p>\n                        <p class=\"mb-2 editable-field\" data-block-key=\"service.resubmission-one-version.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">\n                          The authors are however able to:\n                        </p>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.resubmission-one-version.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">Make changes to text in galley</li>\n                          <li class=\"editable-field\" data-block-key=\"service.resubmission-one-version.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">Make changes to cover text or design</li>\n                          <li class=\"editable-field\" data-block-key=\"service.resubmission-one-version.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">Change subtitle</li>\n                        </ul>\n                        <p class=\"mb-0 editable-field\" data-block-key=\"service.resubmission-one-version.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-one-version', this)\">\n                          If you have a paperback and a hardcover version you want to update, please see our service for <a href=\"/services?service=resubmission-two-version\" class=\"service-inline-link fw-semibold\" style=\"color: #ad7d42;\">Resubmission (Two Versions)</a>.\n                        </p>\n                      </div>\n                    </div>",
  "resubmission-two-version": "<div class=\"resubmission-two-version-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.resubmission-two-version.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">\n                          When a book has gone live and the author finds problems, errors, or other issues that need to be corrected, we can re-submit the file to the printer to update future copies.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.resubmission-two-version.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">\n                          Note: If the author is resubmitting to do a re-tech, then the price of the re-tech is reduced from $275 to $250 when purchased with the resubmission.\n                        </p>\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.resubmission-two-version.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">\n                          Please remember that the title and the price (Omni bookstore or retail) for a book going through resubmission cannot be changed after it has gone live.\n                        </p>\n                        <p class=\"mb-2 editable-field\" data-block-key=\"service.resubmission-two-version.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">\n                          The authors are however able to:\n                        </p>\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem;\">\n                          <li class=\"editable-field\" data-block-key=\"service.resubmission-two-version.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">Make changes to text in galley</li>\n                          <li class=\"editable-field\" data-block-key=\"service.resubmission-two-version.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">Make changes to cover text or design</li>\n                          <li class=\"editable-field\" data-block-key=\"service.resubmission-two-version.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">Change subtitle</li>\n                        </ul>\n                        <p class=\"mb-0 editable-field\" data-block-key=\"service.resubmission-two-version.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('resubmission-two-version', this)\">\n                          If your book is available in only one format, such as paperback only or hardcover only, learn more about our service for <a href=\"/services?service=resubmission-one-version\" class=\"service-inline-link fw-semibold\" style=\"color: #ad7d42;\">Resubmission (One Version)</a>.\n                        </p>\n                      </div>\n                    </div>",
  "bookblast-video-marketing-stand-alone-30days": "<div class=\"bookblast-video-marketing-stand-alone-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                          Go the extra mile with your marketing campaign, and place your video as an ad on YouTube. Seize the opportunity to have your book video introduced as an advertising break before, or in between, YouTube videos. Your book information, purchase and availability details are displayed when the ad is clicked.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.h1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                          What you get:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                            A 30-day* ad placement campaign on YouTube that gives viewers a preview of your book. Your ad will appear at the beginning of a YouTube video, or in between videos. Viewers can get more information about your book by clicking on the video, which redirects them to either your book's online bookstore page or your own book website.\n                          </li>\n                        </ul>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                          Please note that you may sign up for this package only if you have purchased any of the following Omni book video services:\n                        </p>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li>\n                            <a href=\"/services?service=standard-book-video\" class=\"service-inline-link fw-semibold\" style=\"color: #ad7d42;\">Standard Book Video</a>\n                          </li>\n                          <li>\n                            <a href=\"/services?service=premium-book-video\" class=\"service-inline-link fw-semibold\" style=\"color: #ad7d42;\">Premium Book Video</a>\n                          </li>\n                        </ul>\n\n                        <p class=\"mb-4 fst-italic editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                          *Want to have a longer campaign period? Contact your marketing consultant to get a custom quote for your video campaign.\n                        </p>\n\n                        <div class=\"more-about-section mb-4\">\n                          <h6 class=\"fw-bold mb-1 editable-field\" style=\"color: #2b2219; font-size: 0.98rem;\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.more_title\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                            More About | Bookblast Video Marketing - Standalone (30 Days)\n                          </h6>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.95rem; line-height: 1.7;\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.more_desc\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                            Catch the curiosity and interest of YouTube viewers to increase your reach – and potential book sales.\n                          </p>\n                        </div>\n\n                        <p class=\"disclaimer-text fst-italic text-muted mt-5 pt-3 editable-field\" style=\"font-size: 0.84rem; line-height: 1.6; border-top: 1px solid rgba(0, 0, 0, 0.08);\" data-block-key=\"service.bookblast-video-marketing-stand-alone-30days.disclaimer\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-stand-alone-30days', this)\">\n                          Disclaimer: Prices listed do not include applicable taxes (such as sales, use, excise, value-added, goods and services, or other tax), which will be added to the total at the time of purchase. Prices listed do include the copies of the book; the cost of shipping and handling will be calculated and charged after your book is made available for sale.\n                        </p>\n                      </div>\n                    </div>",
  "standard-book-video": "<div class=\"standard-book-video-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.standard-book-video.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                          A Standard Book Video can help you create and maintain a meaningful presence online in the competitive marketplace. Video book videos are an excellent addition to your press releases, social media sites, and personal websites to help your book stand out in the crowd.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.standard-book-video.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                          By posting your video on social media sites and personal websites you can reach a valuable audience of online video viewers and attract potential readers. Video marketing helps you engage your audience on a level they can’t ignore.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.standard-book-video.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                          Take a look at Ernst Aebi's Standard Book Video showcasing his book Seasons of Sand Sahara.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.standard-book-video.h1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                          Our Standard Book Video includes the following features:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                            Creation of a custom-made video book video, approximately 45 to 60 seconds in length\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                            Storytelling through text and 2-D graphics and image\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                            Distribution of your video to YouTube in order to maximize exposure\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                            Web streaming capability\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                            Review of your video for TV and film consideration by 5 More Minutes\n                          </li>\n                        </ul>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.standard-book-video.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                          You will own all the rights to your book video and will be provided with the final video file to share with readers, friends, and family and include in your marketing materials.\n                        </p>\n\n                        <p class=\"mb-2 editable-field\" data-block-key=\"service.standard-book-video.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                          <strong>Revisions:</strong> You will be able to make one round of revisions to your video at no additional cost. Any additional rounds of revisions will cost an additional fee. Acceptable changes include:\n                        </p>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.rev1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Simple text changes</li>\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.rev2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Changes in font size</li>\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.rev3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Corrections or additions to book and author information</li>\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.rev4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Changes to audio levels</li>\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.rev5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">Image changes (if you provided your own or you feel an image is offensive)</li>\n                        </ul>\n\n                        <p class=\"mb-2 editable-field\" data-block-key=\"service.standard-book-video.p6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                          Once your video is completed, it will be considered for TV or movie adaption by 5 More Minutes.\n                        </p>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.hly1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                            If 5 More Minutes is interested in working with you, they will directly contact you to explain their plan of action to gauge your interest.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.standard-book-video.hly2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                            If after reviewing your video 5 More Minutes decides not to engage with your concept, it will then be entered into our Hollywood Database, where registered entertainment professionals can browse and search for new material to adapt into feature films and television series.\n                          </li>\n                        </ul>\n\n                        <div class=\"about-5mm-card p-4 rounded-3 mt-4\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <div class=\"row align-items-center g-4\">\n                            <div class=\"col-12 col-md-4 text-center\">\n                              <img src=\"/assets/img/5mm.png\" alt=\"5 More Minutes Logo\" class=\"img-fluid\" style=\"max-width: 280px; width: 100%; height: auto;\" />\n                            </div>\n                            <div class=\"col-12 col-md-8\">\n                              <h4 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.25rem;\" data-block-key=\"service.standard-book-video.about_title\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                                About 5 More Minutes\n                              </h4>\n                              <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.93rem; line-height: 1.72;\" data-block-key=\"service.standard-book-video.about_desc\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('standard-book-video', this)\">\n                                5 More Minutes is a full-service production shingle run by veteran Hollywood executive John Sacchi. Sacchi has spent over two decades in the entertainment industry. Before founding 5 More Minutes, Sacchi spent 15 years as a senior production and development executive at Lionsgate Films where he oversaw films including Confidence, Employee of the Month, They Came Together, My Bloody Valentine, The Possession, Killers, The Last Stand, Addicted, Conan the Barbarian, Punisher, My Best Friend’s Girl, Pride, and Akeelah and the Bee. Some of the current projects 5 More Minutes is developing include an English language remake of <em>Instructions not Included</em>, directed by Anne Fletcher for Lionsgate; <em>Vanish Man</em> directed by Lee Toland Krieger and co-produced for 21 Laps and Lionsgate; <em>Dork Diaries</em>, which is based on the New York Times best selling children's book series and produced for Lionsgate; and the New York Times best selling author's <em>Rogues Gallery</em>, which is being produced for Lionsgate Television.\n                              </p>\n                            </div>\n                          </div>\n                        </div>\n                      </div>\n                    </div>",
  "premium-book-video": "<div class=\"premium-book-video-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.premium-book-video.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                          Give your fans a sensational preview of your book with the Premium Book Video. Complete with professional voiceover, your custom video will enhance your book marketing efforts and help your book stand out in the crowd. Plus, a Premium Book Video makes an excellent addition to your press releases, social media sites, and personal websites.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.premium-book-video.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                          Take a look at Barbara L. Kananen's <strong>Premium Book Video</strong> showcasing her book Fairies in My Garden.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.premium-book-video.h1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                          Our Premium Book Video includes the following features:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                            Creation of a custom-made video book video, approximately 60 to 90 seconds in length\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                            Audible storytelling through voiceover by a professional actor\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                            Imagery includes complex design, such as lighting effects, 3-D space, visual effects and motion graphics\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                            Two live-action video clips\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                            Distribution of your video to YouTube in order to maximize exposure\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                            Web streaming capability\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.li7\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                            Review of your video for TV and film consideration by 5 More Minutes.\n                          </li>\n                        </ul>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.premium-book-video.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                          You will own all the rights to your book video and will be provided with the final video file to share with readers, friends, and family and include in your marketing materials.\n                        </p>\n\n                        <p class=\"mb-2 editable-field\" data-block-key=\"service.premium-book-video.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                          <strong>Revisions:</strong> You will be able to make one round of revisions to your video at no additional cost. Any additional rounds of revisions will cost an additional fee. Acceptable changes include:\n                        </p>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.rev1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Simple text changes</li>\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.rev2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Changes in font size</li>\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.rev3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Corrections or additions to book and author information</li>\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.rev4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Changes to audio levels</li>\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.rev5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">Image changes (if you provided your own or you feel an image is offensive)</li>\n                        </ul>\n\n                        <p class=\"mb-2 editable-field\" data-block-key=\"service.premium-book-video.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                          Once your video is completed, it will be considered for TV or movie adaption by 5 More Minutes.\n                        </p>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.hly1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                            If 5 More Minutes is interested in working with you, they will contact you directly and explain their plan of action to gauge your interest.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.premium-book-video.hly2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                            If after reviewing your book video 5 More Minutes decides not to engage on your project, your screenplay will be added into our exclusive Hollywood Database where it will be accessible to directors, producers, actors and agents.\n                          </li>\n                        </ul>\n\n                        <div class=\"about-5mm-card p-4 rounded-3 mt-4\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <div class=\"row align-items-center g-4\">\n                            <div class=\"col-12 col-md-4 text-center\">\n                              <img src=\"/assets/img/5mm.png\" alt=\"5 More Minutes Logo\" class=\"img-fluid\" style=\"max-width: 280px; width: 100%; height: auto;\" />\n                            </div>\n                            <div class=\"col-12 col-md-8\">\n                              <h4 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.25rem;\" data-block-key=\"service.premium-book-video.about_title\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                                About 5 More Minutes\n                              </h4>\n                              <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.93rem; line-height: 1.72;\" data-block-key=\"service.premium-book-video.about_desc\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('premium-book-video', this)\">\n                                5 More Minutes is a full-service production shingle run by veteran Hollywood executive John Sacchi. Sacchi has spent over two decades in the entertainment industry. Before founding 5 More Minutes, Sacchi spent 15 years as a senior production and development executive at Lionsgate Films where he oversaw films including Confidence, Employee of the Month, They Came Together, My Bloody Valentine, The Possession, Killers, The Last Stand, Addicted, Conan the Barbarian, Punisher, My Best Friend’s Girl, Pride, and Akeelah and the Bee. Some of the current projects 5 More Minutes is developing include an English language remake of <em>Instructions not Included</em>, directed by Anne Fletcher for Lionsgate; <em>Vanish Man</em> directed by Lee Toland Krieger and co-produced for 21 Laps and Lionsgate; <em>Dork Diaries</em>, which is based on the New York Times best selling children's book series and produced for Lionsgate; and the New York Times best selling author's <em>Rogues Gallery</em>, which is being produced for Lionsgate Television.\n                              </p>\n                            </div>\n                          </div>\n                        </div>\n                      </div>\n                    </div>",
  "bookblast-video-marketing-standard": "<div class=\"bookblast-video-marketing-standard-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.bookblast-video-marketing-standard.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">\n                          The appeal of a book video is undeniable – and the numbers show it. YouTube has over a billion video viewers, and every day, people watch hundreds of millions of hours on YouTube. Make sure your book catches the attention of an engaged and influential audience of online video viewers with the creation of your book video and your YouTube advertising campaign.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.bookblast-video-marketing-standard.h1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">\n                          What you get:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-standard.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">\n                            One <a href=\"/services?service=standard-book-video\" class=\"service-inline-link fw-semibold\" style=\"color: #ad7d42;\">Standard Book Video</a> marketing service\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-standard.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">\n                            A 30-second version of the Standard Book Video to be used in the YouTube campaign.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-standard.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">\n                            A 30-day ad placement campaign on YouTube that gives viewers a preview of your book. Your ad will appear at the beginning of a YouTube video, or in between videos. Viewers can get more information about your book by clicking on the video, which redirects them to either your book’s online bookstore page or your own book website.\n                          </li>\n                        </ul>\n\n                        <p class=\"disclaimer-text fst-italic text-muted mt-5 pt-3 editable-field\" style=\"font-size: 0.84rem; line-height: 1.6; border-top: 1px solid rgba(0, 0, 0, 0.08);\" data-block-key=\"service.bookblast-video-marketing-standard.disclaimer\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-standard', this)\">\n                          Disclaimer: Prices listed do not include applicable taxes (such as sales, use, excise, value-added, goods and services, or other tax), which will be added to the total at the time of purchase. Prices listed do include the copies of the book; the cost of shipping and handling will be calculated and charged after your book is made available for sale.\n                        </p>\n                      </div>\n                    </div>",
  "bookblast-video-marketing-premium": "<div class=\"bookblast-video-marketing-premium-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.bookblast-video-marketing-premium.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">\n                          Strengthen your book’s presence in the marketplace, and boost its selling potential, by showcasing it on YouTube. With this advertising package, you now have the means to widen your reach and attract more readers. YouTube has over a billion video viewers, and every day, people watch hundreds of millions of hours on YouTube. Capture their curiosity by inviting a professional voice actor to narrate your book video, and hold their attention with a strategic YouTube video advertising campaign that targets viewers with keen interest in your book’s genre and style.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.bookblast-video-marketing-premium.h1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">\n                          What you get:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-premium.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">\n                            One <a href=\"/services?service=premium-book-video\" class=\"service-inline-link fw-semibold\" style=\"color: #ad7d42;\">Premium Book Video</a> marketing service\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-premium.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">\n                            A 30-second version of the Premium Book Video to be used in the YouTube campaign.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.bookblast-video-marketing-premium.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">\n                            A 30-day ad placement campaign on YouTube that gives viewers a preview of your book. Your ad will appear at the beginning of a YouTube video, or in between videos. Viewers can get more information about your book by clicking on the video, which redirects them to either your book’s online bookstore page or your own book website.\n                          </li>\n                        </ul>\n\n                        <p class=\"disclaimer-text fst-italic text-muted mt-5 pt-3 editable-field\" style=\"font-size: 0.84rem; line-height: 1.6; border-top: 1px solid rgba(0, 0, 0, 0.08);\" data-block-key=\"service.bookblast-video-marketing-premium.disclaimer\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('bookblast-video-marketing-premium', this)\">\n                          Disclaimer: Prices listed do not include applicable taxes (such as sales, use, excise, value-added, goods and services, or other tax), which will be added to the total at the time of purchase. Prices listed do include the copies of the book; the cost of shipping and handling will be calculated and charged after your book is made available for sale.\n                        </p>\n                      </div>\n                    </div>",
  "15-sec-video-marketing": "<div class=\"fifteen-sec-video-marketing-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.15-sec-video-marketing.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                          With over two billion monthly visitors* (and that’s only counting logged-in users!), it’s no secret that YouTube has become a staple in our daily lives.\n                        </p>\n\n                        <p class=\"mb-4 fw-semibold editable-field\" style=\"color: #2b2219;\" data-block-key=\"service.15-sec-video-marketing.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                          One exciting and impactful way to promote your book is through short video ads on YouTube. It gets your book the attention of an engaged and captive audience on the biggest online video platform in the world today**.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.15-sec-video-marketing.h1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                          Here’s what you get with the 15-Sec Video Marketing service:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.15-sec-video-marketing.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                            A 15-second custom-made video ad of your book with a professional voice over\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.15-sec-video-marketing.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                            Your video ad shown 350,000 times on YouTube.<br>Your entire ad will play uninterrupted at the start, midway, or towards the end before the main video can continue.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.15-sec-video-marketing.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                            Custom banner of your book that links to the ordering page and displayed alongside your video ad (for desktop)\n                          </li>\n                        </ul>\n\n                        <p class=\"mb-4 fst-italic editable-field\" style=\"color: #57534e; font-size: 0.94rem;\" data-block-key=\"service.15-sec-video-marketing.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                          Here’s how a 15-sec ad will look like on desktop.\n                        </p>\n\n                        <div class=\"sources-note p-3 rounded-3 mb-0\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-1 fst-italic editable-field\" style=\"color: #57534e; font-size: 0.85rem; line-height: 1.6;\" data-block-key=\"service.15-sec-video-marketing.source1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                            * https://www.youtube.com/about/press/\n                          </p>\n                          <p class=\"mb-0 fst-italic editable-field\" style=\"color: #57534e; font-size: 0.85rem; line-height: 1.6;\" data-block-key=\"service.15-sec-video-marketing.source2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('15-sec-video-marketing', this)\">\n                            ** https://www.statista.com/topics/2019/youtube/\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "video-book-talk": "<div class=\"video-book-talk-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.video-book-talk.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                          Your book shouldn't be confined to a box, whether that's your bookshelf, a storage container, or the four walls of traditional media.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.video-book-talk.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                          It should be where readers are. Ride the streaming trend with Roku's 70M users, Amazon Fire TV's 50M users, and YouTube's 1B users, and reach new audiences with Video Book Talk!\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.video-book-talk.h1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                          Inclusions:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.video-book-talk.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                            <strong>Video Interview on the Talking Books show with JT Crowley:</strong> A pre-recorded 15-20 minute interview with British author and host JT Crowley. The video will be on top streaming services such as Roku, Amazon Fire TV, and YouTube; and available on ExpertsandAuthors.tv and WebTalkRadio.net.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.video-book-talk.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                            <strong>Audio podcast:</strong> An audio-only interview version will be available on Apple Podcasts, Spotify, iHeart Radio, and other aggregators.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.video-book-talk.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                            Social media post sharing your video interview on our active social media pages.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.video-book-talk.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                            A link to the video interview, which you can use on your promotional activities.\n                          </li>\n                        </ul>\n\n                        <p class=\"mb-4 fw-medium editable-field\" style=\"color: #2b2219;\" data-block-key=\"service.video-book-talk.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                          Increase your book's visibility and connect with readers in a new, engaging, and innovative way with Video Book Talk.\n                        </p>\n\n                        <div class=\"about-jt-crowley-card p-4 rounded-3 mt-4\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h5 class=\"fw-bold mb-2 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.video-book-talk.about_title\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                            About JT Crowley\n                          </h5>\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.93rem; line-height: 1.72;\" data-block-key=\"service.video-book-talk.about_desc\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('video-book-talk', this)\">\n                            JT Crowley is a British author whose global adventures and humble beginnings shaped his passion for storytelling. Join him on the Talking Books show as he chats with diverse authors about the magic behind their captivating stories.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "indie-book-review-bundle": "<div class=\"indie-book-review-bundle-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.indie-book-review-bundle.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                          As a self-published author in the competitive literary industry, securing as many book reviews as you can get helps you stand out. Your potential readers look to professional reviews to get an indication of the quality of a book, so you need to partner with the pros – like BookLife Reviews.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.indie-book-review-bundle.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                          BookLife is a website created by <em>Publishers Weekly</em>, that focuses on supporting indie authors. Since 2014, the site has become a haven for authors who want to navigate the complex literary industry and to connect with like-minded writers.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.indie-book-review-bundle.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                          Just like Omni, BookLife is also dedicated to helping self-published authors achieve their publishing goals. So we've teamed up with them to create the Indie Book Review Bundle. This service doesn't only give you a comprehensive review crafted by professional <em>Publishers Weekly</em> reviewers under the BookLife Reviews brand; you'll also benefit from a variety of marketing campaigns!\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.indie-book-review-bundle.h1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                          With this service you get:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"mb-3 editable-field\" data-block-key=\"service.indie-book-review-bundle.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                            <strong>An extensive book review by BookLife* that includes:</strong>\n                            <ul class=\"ps-3 mt-2 d-flex flex-column gap-2\" style=\"list-style-type: circle; color: #57534e; font-size: 0.93rem;\">\n                              <li>A 300-word review that covers the plot summary, critique, and analysis of your book. It will also include an assessment of which readers are most likely to enjoy the book.</li>\n                              <li>An honest, positive one-sentence takeaway that summarizes the reviewer's opinion of the book's best aspects and likely audience.</li>\n                              <li>A list of comparison (comp) titles and/or authors.</li>\n                              <li>Letter grades (from A+ to C) for five production elements: cover art, interior design and typography, illustrations (if applicable), editing, and marketing copy.</li>\n                            </ul>\n                          </li>\n                          <li class=\"mb-3 editable-field\" data-block-key=\"service.indie-book-review-bundle.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                            <strong>Online banner ad campaign on PublishersWeekly.com with 10,000 impressions:</strong>\n                            <ul class=\"ps-3 mt-2\" style=\"list-style-type: circle; color: #57534e; font-size: 0.93rem;\">\n                              <li>You’ll get a banner featuring your book that will be shown in PublishersWeekly.com. The site has over 14 million annual unique visitors.</li>\n                            </ul>\n                          </li>\n                          <li class=\"mb-3 editable-field\" data-block-key=\"service.indie-book-review-bundle.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                            <strong>1 out of 8 ad slot in a Publishers Weekly Supplement:</strong>\n                            <ul class=\"ps-3 mt-2 d-flex flex-column gap-2\" style=\"list-style-type: circle; color: #57534e; font-size: 0.93rem;\">\n                              <li>Depending on your book’s availability, your book ad will appear alongside seven other titles in one of the next available Publishers Weekly’s stand-alone supplements. The Publishers Weekly Supplement is handed out to attendees in specific industry events or conferences. Learn more about the supplements below.</li>\n                              <li>Each of the supplements is also center-stitched to a corresponding Publishers Weekly magazine, which is distributed to Publishers Weekly’s 68,000 print subscribers on the same week as the industry event or conference.</li>\n                            </ul>\n                          </li>\n                        </ul>\n\n                        <div class=\"table-responsive my-4\">\n                          <table class=\"table table-bordered mb-0\" style=\"border-color: #ebd9c4; font-size: 0.92rem;\">\n                            <thead style=\"background-color: #fbf7f2;\">\n                              <tr>\n                                <th style=\"color: #2b2219; font-weight: 600; padding: 12px 16px;\">Supplement for</th>\n                                <th style=\"color: #2b2219; font-weight: 600; padding: 12px 16px;\">Publication date**</th>\n                                <th style=\"color: #2b2219; font-weight: 600; padding: 12px 16px;\">Facts</th>\n                              </tr>\n                            </thead>\n                            <tbody>\n                              <tr>\n                                <td style=\"color: #2b2219; font-weight: 600; padding: 12px 16px; white-space: nowrap;\">Winter Institute</td>\n                                <td style=\"color: #57534e; padding: 12px 16px; white-space: nowrap;\">January</td>\n                                <td style=\"color: #44403c; line-height: 1.6; padding: 12px 16px;\">A convention for the owners and staff of independent booksellers in the US. It is a place where booksellers hear about publishers’ picks for forthcoming books for their audiences.</td>\n                              </tr>\n                              <tr>\n                                <td style=\"color: #2b2219; font-weight: 600; padding: 12px 16px; white-space: nowrap;\">Children’s Institute</td>\n                                <td style=\"color: #57534e; padding: 12px 16px; white-space: nowrap;\">June</td>\n                                <td style=\"color: #44403c; line-height: 1.6; padding: 12px 16px;\">An annual conference that includes a 3-day forum, workshops, keynotes, and trainings with more than 330 booksellers from 44 states gather in the conference, including 62 scholarship recipients, and 230 participating stores. It was this diversity of attendees – from owners and senior staff to frontline booksellers, and from large stores to microstores – that fostered an atmosphere that was at turns both explosive and enthralling.</td>\n                              </tr>\n                              <tr>\n                                <td style=\"color: #2b2219; font-weight: 600; padding: 12px 16px; white-space: nowrap;\">Star Watch</td>\n                                <td style=\"color: #57534e; padding: 12px 16px; white-space: nowrap;\">September</td>\n                                <td style=\"color: #44403c; line-height: 1.6; padding: 12px 16px;\">It is a Publishers Weekly annual event in association with Frankfurter Buchmesse, which identifies and celebrates members of the US and Canadian publishing communities who are blazing trails and doing innovative work.</td>\n                              </tr>\n                              <tr>\n                                <td style=\"color: #2b2219; font-weight: 600; padding: 12px 16px; white-space: nowrap;\">AAR &amp; SBL</td>\n                                <td style=\"color: #57534e; padding: 12px 16px; white-space: nowrap;\">November</td>\n                                <td style=\"color: #44403c; line-height: 1.6; padding: 12px 16px;\">It is the world’s largest gathering of scholars interested in the study of religion. This event includes an exhibit hall with more than 130 publishers exhibiting – the best place to review the latest publications within the field.</td>\n                              </tr>\n                            </tbody>\n                          </table>\n                        </div>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.indie-book-review-bundle.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                          As an indie author, you control when your BookLife review is made public through a BookLife account created for you. When you publish your review, you get these bonus features*** to help you get more marketing buzz for your book:\n                        </p>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"mb-2 editable-field\" data-block-key=\"service.indie-book-review-bundle.b1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                            The entire review published in one of the monthly BookLife sections on the <em>Publishers Weekly</em> print magazine sent to its 68,000 subscribers. We’ll send you a free copy of the issue where your book review appears!\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.indie-book-review-bundle.b2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                            BookLife submits a copy of your book review to industry database systems such as EBSCO, Ingram and Proquest, making your review accessible to all bookstores and online retailers.\n                          </li>\n                        </ul>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.92rem;\">Please note:</h6>\n                          <p class=\"mb-2 fst-italic editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.6;\" data-block-key=\"service.indie-book-review-bundle.n1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                            * This service is most suitable for books that are in English, with not more than 150,000 words, and are commercially available in the US.\n                          </p>\n                          <p class=\"mb-2 fst-italic editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.6;\" data-block-key=\"service.indie-book-review-bundle.n2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                            ** Publication dates are subject to change according to the show schedules set by the event organizers without prior notice. Please contact Omni to confirm dates for you.\n                          </p>\n                          <p class=\"mb-2 fst-italic editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.6;\" data-block-key=\"service.indie-book-review-bundle.n3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                            *** Fulfillment of bonus features require the BookLife review to be published on BookLife.com.\n                          </p>\n                          <p class=\"mb-0 fw-medium editable-field\" style=\"color: #7c5e2a; font-size: 0.85rem;\" data-block-key=\"service.indie-book-review-bundle.src\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('indie-book-review-bundle', this)\">\n                            Data Source: PW Media Kit\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "literary-gateway-bundle": "<div class=\"literary-gateway-bundle-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.literary-gateway-bundle.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                          A book award is more than a feather in your cap or an emblem on the front cover. Awards make books more valuable in the eyes of the ordinary consumer. It helps boost credibility, create awareness of the book, and even grow one’s audience. It’s a marketing tool not often explored but one that you, as an author, shouldn’t overlook.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.literary-gateway-bundle.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                          Finding the right literary award to enter and submitting a professional application, can be both daunting and time-consuming tasks. Omni simplifies the process for you with Literary Gateway, so you can explore award opportunities at your fingertips easily and get a professional book review to help you build your author brand.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.literary-gateway-bundle.h1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                          What does the Literary Gateway service include?\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"mb-3 editable-field\" data-block-key=\"service.literary-gateway-bundle.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                            <strong>6 months access to Awards Finder:</strong><br>AwardsFinder is a book award-matching platform that finds you one award opportunity per week throughout your 6-month access. On a monthly basis, AwardsFinder will target one literary award opportunity as the best match, create the nomination package for your book and professionally submit the entry of your behalf.\n                          </li>\n                          <li class=\"mb-3 editable-field\" data-block-key=\"service.literary-gateway-bundle.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                            <strong>BlueInk Review:</strong><br>Blueink Review, the brainchild of an internationally known literary agent and an award-winning book review editor, was created with a specific purpose: to respectfully and professionally find and celebrate the best of self-published books. Your Blueink review is a 250- to 300-word objective book review that considers facts and style as the reviewer deems appropriate. Your book review will be posted on the BlueInk website, unless requested otherwise.\n                          </li>\n                          <li class=\"mb-3 editable-field\" data-block-key=\"service.literary-gateway-bundle.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                            <strong>Eligibility for a feature on BookMad:</strong><br>If you win an award, it will be featured in BookMad Magazine, an online publication dedicated to empower self-published authors. It will also be announced on Bookmad’s Facebook page.\n                          </li>\n                          <li class=\"editable-field\" data-block-key=\"service.literary-gateway-bundle.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                            <strong>Option for Cover Resubmission:</strong><br>To add the review blurb and/or any award seals to your book cover.\n                          </li>\n                        </ul>\n\n                        <div class=\"faq-callout p-3 rounded-3 mb-0\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.literary-gateway-bundle.faq\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('literary-gateway-bundle', this)\">\n                            Got more questions? Visit the Literary Gateway Bundle FAQs page &gt;\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "review-duo": "<div class=\"review-duo-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.review-duo.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                          Spark reader’s interest and build credibility for your book with the <strong>Review Duo</strong> service. Receive professional, unbiased assessments for your book from these esteemed book reviewers:\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.review-duo.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                          <strong>The Pacific Book Review (PBR)</strong> - The PBR staff specializes in authoritative, objective book reviews, written by specialists selected for their knowledge and expertise in each genre. PBR aggressively markets its site through social networking, email marketing, publishing conferences, blogging, and other means; they also email out a monthly newsletter to industry professionals.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.review-duo.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                          <strong>The US Review of Books (USRB)</strong> - The USRB staff reviews all types of books and will introduce your book to more than 14,000 subscribers in its monthly newsletter. Your book will also be showcased on the Featured Book Reviews section on the USRB website.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.review-duo.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                          In addition to these respected book reviews, the <strong>Review Duo</strong> includes entry to the prestigious Eric Hoffer Award as well as the Pacific Book Awards. Established in 2005, the Hoffer Award recognizes “salient writing, as well as the independent spirit of small publishers,” as a tribute to American philosopher and author Eric Hoffer. Winners are featured on the USRB website. Founded by Nicole Sorkin in 2013, an entrepreneur who has helped countless authors, the Pacific Book Award was created to celebrate both print and electronic books.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.review-duo.h1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                          Review Duo includes:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.review-duo.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">PBR Book Review</li>\n                          <li class=\"editable-field\" data-block-key=\"service.review-duo.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">USRB Book Review</li>\n                          <li class=\"editable-field\" data-block-key=\"service.review-duo.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">Entry to the Eric Hoffer Award</li>\n                          <li class=\"editable-field\" data-block-key=\"service.review-duo.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">Entry to the Pacific Book Awards</li>\n                          <li class=\"editable-field\" data-block-key=\"service.review-duo.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">Free cover revision option to include a portion of the reviews on the cover</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 fst-italic editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.6;\" data-block-key=\"service.review-duo.note\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo', this)\">\n                            Please Note: In the event a returned review is unfavorable, the author can choose not to use it in their marketing efforts; however, the fees for the Review Duo Review Service cannot be refunded.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "review-duo-plus": "<div class=\"review-duo-plus-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.review-duo-plus.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                          Spark reader’s interest and build credibility for your book with the <strong>Review Duo Plus</strong> service. Receive professional, unbiased assessments for your book from these esteemed book reviewers:\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.review-duo-plus.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                          <strong>The Pacific Book Review (PBR)</strong> - The PBR staff specializes in authoritative, objective book reviews, written by specialists selected for their knowledge and expertise in each genre. PBR aggressively markets its site through social networking, email marketing, publishing conferences, blogging, and other means; they also email out a monthly newsletter to industry professionals.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.review-duo-plus.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                          <strong>The US Review of Books (USRB)</strong>- The USRB staff reviews all types of books and will introduce your book to more than 14,000 subscribers in its monthly newsletter. Your book will also be showcased on the Featured Book Reviews section on the USRB website.\n                        </p>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.review-duo-plus.p4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                          <strong>Review Duo Plus</strong> includes a 10-15 minute <strong>Online Radio Interview</strong>, syndicated via iTunes and Toginet.com. It’s digitally retrievable for use on mobile devices (iPhone, iPad, etc.), and can be used for all of your marketing activities.\n                        </p>\n\n                        <p class=\"mb-4 editable-field\" data-block-key=\"service.review-duo-plus.p5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                          In addition to these respected book reviews, the <strong>Review Duo Plus</strong> includes entry to the prestigious Eric Hoffer Award as well as the Pacific Book Awards. Established in 2005, the Hoffer Award recognizes “salient writing, as well as the independent spirit of small publishers,” as a tribute to American philosopher and author Eric Hoffer. Winners are featured on the USRB website. Founded by Nicole Sorkin in 2013, an entrepreneur who has helped countless authors, the Pacific Book Award was created to celebrate both print and electronic books.\n                        </p>\n\n                        <h5 class=\"fw-bold mb-3 editable-field\" style=\"color: #2b2219; font-size: 1.05rem;\" data-block-key=\"service.review-duo-plus.h1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                          Review Duo includes:\n                        </h5>\n\n                        <ul class=\"mb-4 ps-3 d-flex flex-column gap-2\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.75;\">\n                          <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">PBR Book Review</li>\n                          <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">USRB Book Review, including placement in their Featured Book Reviews section for one month</li>\n                          <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">10-15 minute Online Radio Interview, available for download on popular sites such as iTunes</li>\n                          <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">Entry to the Eric Hoffer Award</li>\n                          <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li5\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">Entry to the Pacific Book Awards</li>\n                          <li class=\"editable-field\" data-block-key=\"service.review-duo-plus.li6\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">Free cover revision option to include a portion of the reviews on the cover</li>\n                        </ul>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 fst-italic editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.6;\" data-block-key=\"service.review-duo-plus.note\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('review-duo-plus', this)\">\n                            Please Note: In the event a returned review is unfavorable, the author can choose not to use it in their marketing efforts; however, the fees for the Review Duo Review Service cannot be refunded.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "the-trifecta-review-service": "<div class=\"the-trifecta-review-service-detail-content\">\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.the-trifecta-review-service.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                          Get unbiased and professional reviews from three different esteemed publications. With the <strong>Omni Trifecta Review Service*</strong> your marketing efforts will receive an extra boost and give your book that much-needed edge.\n                        </p>\n\n                        <div class=\"mb-4\">\n                          <div class=\"mb-3\">\n                            <strong style=\"color: #2b2219; font-size: 1.02rem;\">Kirkus Indie</strong>\n                            <p class=\"mb-0 mt-1 editable-field\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.7;\" data-block-key=\"service.the-trifecta-review-service.kirkus\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                              Among the world’s highly acclaimed book review providers, Kirkus Indie delivers honest and fair critiques of your work. Go beyond the ordinary and increase your visibility with a Kirkus review.\n                            </p>\n                          </div>\n\n                          <div class=\"mb-3\">\n                            <strong style=\"color: #2b2219; font-size: 1.02rem;\">Clarion Review-for-Fee</strong>\n                            <p class=\"mb-0 mt-1 editable-field\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.7;\" data-block-key=\"service.the-trifecta-review-service.clarion\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                              ForeWord Magazine’s paid review service heavily influences the decisions of booksellers and librarians across the country. Clarion is ForeWord’s solution to the increasing demand for a qualified and impartially written review for self-published titles. Expect to receive reviews from the experts of specific genres that promise the same high quality as any other reputable review service.\n                            </p>\n                          </div>\n\n                          <div class=\"mb-0\">\n                            <strong style=\"color: #2b2219; font-size: 1.02rem;\">BlueInk Review</strong>\n                            <p class=\"mb-0 mt-1 editable-field\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.7;\" data-block-key=\"service.the-trifecta-review-service.blueink\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                              Dedicated to exclusively providing honest, unbiased reviews, BlueInk Review caters exclusively to self-published titles. Created by two trade professionals—an internationally respected literary agent and a widely acclaimed book review editor—this company boasts of carefully vetted independent critics. Everything about BlueInk Review is born of its founders’ vast expertise in the literary world.\n                            </p>\n                          </div>\n                        </div>\n\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.the-trifecta-review-service.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                          A review can influence the market’s awareness towards your book. The Omni Trifecta Review Service enhances and gives your bookselling strategy an edge among the rest.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <strong style=\"color: #2b2219; font-size: 1.02rem;\">Kirkus Magazine (1 of 8 slots)</strong>\n                          <p class=\"mb-0 mt-1 editable-field\" style=\"color: #44403c; font-size: 0.95rem; line-height: 1.7;\" data-block-key=\"service.the-trifecta-review-service.magazine\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                            Get more print visibility for your book with a black-and-white advertisement within the pages of the Kirkus Reviews magazine. Your book will be one of the eight titles advertised in the page.\n                          </p>\n                        </div>\n\n                        <p class=\"mb-3 fst-italic editable-field\" style=\"color: #57534e; font-size: 0.91rem; line-height: 1.6;\" data-block-key=\"service.the-trifecta-review-service.footnote\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                          *This service includes a cover revision including the book’s review for the authors at no extra cost.\n                        </p>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 fst-italic editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.6;\" data-block-key=\"service.the-trifecta-review-service.note\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('the-trifecta-review-service', this)\">\n                            Please Note: In the event a returned review is unfavorable, the author can choose not to use it in their marketing efforts; however, the fees for the Trifecta Review Service cannot be refunded.\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "join-the-la-times-festival-of-books-2025": "<div class=\"join-the-la-times-festival-of-books-2025-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>Get ready to celebrate the <b>30th anniversary</b> of the L.A. Times Festival of Books on <i>April 26-27, 2025</i> at the University of Southern California campus in Los Angeles.</p>\r\n    \r\n          <p>The Los Angeles Times Festival of Books is one of the largest and most prestigious book festivals in the United States, attracting more than 150,000 booklovers and media members each year. Since its debut in 1996, the festival has joined literature lovers with hundreds of booksellers, publishers, and literary organizations. The <b>LA Times Festival of Books 2025</b> is your chance to meet face-to-face with potential readers and promote your book at this major industry event.</p>\r\n\r\n          <p>Showcase your book for crowds of avid readers to discover by displaying it in the <b><i>Author Solutions Bookstore Gallery</i></b>, or be the star of your own <b><i>book signing</i></b> at the Author Solutions booth.</p>\r\n            <p>Contact your marketing consultant to find out more about these options. Spots will be filled on a first-come, first-served basis, so don't wait.</p>\n  </div>\n</div>",
  "hollywood-coverage": "<div class=\"hollywood-coverage-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>Even with the Internet, it can be quite difficult for most readers to find their next favorite book. But for Ingram’s subscribers, fresh stories aren’t really hard to come by. They know that they can always expect interesting titles from its trusted source: Ingram Advance Catalog Supplements.</p>\r\n          <p><b>HOW IT WORKS:</b></p>  \r\n\r\n            <p>A professional reader will work to develop your book’s coverage, a standard format in the movie and TV industry. Your coverage will consist of two main elements:</p>\r\n                <ul>\r\n                    <li>\r\n                        A thorough synopsis that highlights the main characters and events in your story\r\n                    </li>\r\n                    <li>\r\n                        A critical analysis that addresses key story points as well as how your book might be best adapted for the screen\r\n                    </li>\r\n                </ul>\r\n          \r\n                <p>Once your coverage is prepared, it will be considered for TV or movie adaption by 5 More Minutes.</p>\r\n\r\n                <ul>\r\n                    <li>\r\n                        If 5 More Minutes is interested in working with you, they will contact you directly to explain their plan of action to gauge your interest. \r\n                    </li>\r\n                    <li>\r\n                        If after reviewing your screenplay 5 More Minutes decides not to engage on your project, it will be placed into our Hollywood Database where agents, directors, actors and producers will have access to the information. As an alternative to knocking on the doors of Hollywood agents or cold calling production companies, this service gives you legitimate access to entertainment decision-makers.\r\n                    </li>\r\n                </ul>\r\n                <p><i>* Your Hollywood Coverage will be fulfilled by an independent industry professional who does similar evaluations for the major agencies and studios. Omni has no input regarding the critical analysis your book receives and we cannot guarantee results the evaluation will yield.</i></p>\r\n\r\n                <p>View a Hollywood Coverage example »</p>\r\n\r\n\r\n    <div class=\"about-5mm-block my-4\">\n  <div class=\"about-5mm-logo\">\n    <img src=\"/assets/img/5mm.png\" alt=\"5 More Minutes Logo\" />\n  </div>\n  <div class=\"about-5mm-content\">\n    <h3>About 5 More Minutes</h3>\n    <p>\n      5 More Minutes is a full-service production shingle run by veteran Hollywood executive John Sacchi. Sacchi has spent over two decades in the entertainment industry. Before founding 5 More Minutes, Sacchi spent 15 years as a senior production and development executive at Lionsgate Films where he oversaw films including Confidence, Employee of the Month, They Came Together, My Bloody Valentine, The Possession, Killers, The Last Stand, Addicted, Conan the Barbarian, Punisher, My Best Friend’s Girl, Pride, and Akeelah and the Bee. Some of the current projects 5 More Minutes is developing include an English language remake of <i>Instructions not Included</i>, directed by Anne Fletcher for Lionsgate; <i>Vanish Man</i> directed by Lee Toland Krieger and co-produced for 21 Laps and Lionsgate; <i>Dork Diaries</i>, which is based on the New York Times best selling children's book series and produced for Lionsgate; and the New York Times best selling author's <i>Rogues Gallery</i>, which is being produced for Lionsgate Television.\n    </p>\n  </div>\n</div>\r\n\r\n    <p><h3 style=\"color: rgb(0, 255, 21);\" ><b>More About | Hollywood Coverage</b></h3></p>\r\n    <p>If you’ve ever wondered—even for a moment—if your book could be turned into a movie, Hollywood Coverage is the most cost-effective service that will help you answer that question.</p>\n  </div>\n</div>",
  "hollywood-treatment": "<div class=\"hollywood-treatment-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>\r\n            Your book has all the elements Hollywood wants—an exciting plot, well-developed characters and fresh content—yet there’s still a crucial piece you need in order to be taken seriously by established entertainment executives.\r\n          </p>         \r\n          <p>\r\n            A treatment is a thoroughly developed guide that outlines how a screenwriter would adapt your book into a fully-developed screenplay. As the framework used to transform your work into another medium, Hollywood Treatment is the first step to drafting a screenplay. Not only does it provide the structure for the screenplay, but it also ensures that you and your screenwriter are on the same page regarding the direction your story is taking.\r\n          </p>\r\n          <p>\r\n            By defining exactly how a screenwriter is going to approach the adaption of your book, you eliminate work for agents, studios and producers. By giving them a shortcut to the essence of your book, you can clearly demonstrate that your book has what it takes to succeed on the silver screen.\r\n          </p>\r\n          <p>\r\n            Once your Hollywood Treatment is complete, we will submit it to our first-look Hollywood partner, 5 More Minutes, who will review your work as a potential adaptation for film and television.\r\n          </p>\r\n          <p><b>HOW IT WORKS:</b></p>  \r\n                <ul>\r\n                    <li>\r\n                      From our network of screenwriters, we’ll match you with the one who best complements your book’s story and genre.\r\n                    </li>\r\n                    <li>\r\n                      Your professional screenwriter will provide a thorough five to ten-page treatment detailing how he or she plans to adapt your book’s manuscript into a film and/or television screenplay.\r\n                    </li>\r\n                    <li>\r\n                      Once your treatment is prepared, it will be considered for TV or movie adaption by 5 More Minutes.\r\n                      \r\n                      <ul class=\"inner-list\">\r\n                          <li>\r\n                            If 5 More Minutes is interested in working with you, they will contact you directly and explain their plan of action to gauge your interest.\r\n                          </li>\r\n                          <li>\r\n                            If after reviewing your treatment 5 More Minutes decides not to engage with your concept, we’ll enter your treatment into our Hollywood Database where movie and television writers, agents, directors and producers have access to the information.\r\n                          </li>\r\n                      </ul>\r\n                    </li>\r\n                    <li>\r\n                      The screenwriter waives all rights to the treatment, so you maintain full ownership of your story.\r\n                    </li>\r\n                </ul>\r\n                <p>View a Hollywood Treatment example »</p>\r\n          \r\n                <p><i>Please Note: Hollywood Treatment provides an adaptation based on your book. Details in your plot, characters, etc. may change in order to best fit movie and/or television production. Please <b>do not attempt to contact 5 More Minutes directly</b> or your project will immediately be removed from consideration.</i></p>\r\n             \r\n                \r\n    <div class=\"about-5mm-block my-4\">\n  <div class=\"about-5mm-logo\">\n    <img src=\"/assets/img/5mm.png\" alt=\"5 More Minutes Logo\" />\n  </div>\n  <div class=\"about-5mm-content\">\n    <h3>About 5 More Minutes</h3>\n    <p>\n      5 More Minutes is a full-service production shingle run by veteran Hollywood executive John Sacchi. Sacchi has spent over two decades in the entertainment industry. Before founding 5 More Minutes, Sacchi spent 15 years as a senior production and development executive at Lionsgate Films where he oversaw films including Confidence, Employee of the Month, They Came Together, My Bloody Valentine, The Possession, Killers, The Last Stand, Addicted, Conan the Barbarian, Punisher, My Best Friend’s Girl, Pride, and Akeelah and the Bee. Some of the current projects 5 More Minutes is developing include an English language remake of <i>Instructions not Included</i>, directed by Anne Fletcher for Lionsgate; <i>Vanish Man</i> directed by Lee Toland Krieger and co-produced for 21 Laps and Lionsgate; <i>Dork Diaries</i>, which is based on the New York Times best selling children's book series and produced for Lionsgate; and the New York Times best selling author's <i>Rogues Gallery</i>, which is being produced for Lionsgate Television.\n    </p>\n  </div>\n</div>\n  </div>\n</div>",
  "hollywood-screenplay": "<div class=\"hollywood-screenplay-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>\r\n            Don't just dream about it—take action. If you’re determined to turn your book into a movie or television series, a screenplay is the way to get noticed by Hollywood executives. A screenplay is a fully fleshed out script that television and movie producers can use as a means of evaluating if an adaptation of your book is something they want to produce. With a professionally adapted screenplay, you will let Hollywood know you're serious about breaking into the entertainment business.\r\n        </p>         \r\n          <p>\r\n            Once your Hollywood Screenplay is complete, we will submit your work to our first-look Hollywood partner, 5 More Minutes, who will review your work as a potential adaptation for film and television.\r\n        </p>\r\n          <p><b>HOW IT WORKS:</b></p>  \r\n                <ul>\r\n                    <li>\r\n                     A screenwriter will complete a screenplay based on your approved Hollywood Treatment.\r\n                    </li>\r\n                    <li>\r\n                        Screenplay elements will include character dialogue and detailed action of the story.\r\n                    </li>\r\n                    <li>\r\n                      Once your screenplay is prepared, it will be considered for TV or movie adaption by 5 More Minutes\r\n                      \r\n                      <ul class=\"inner-list\">\r\n                          <li>\r\n                            If 5 More Minutes is interested in working with you, they will contact you directly and explain their plan of action to gauge your interest.\r\n                          </li>\r\n                          <li>\r\n                            If after reviewing your screenplay 5 More Minutes decides not to engage on your project, your screenplay will be added into our exclusive Hollywood Database where it will be accessible to directors, producers, actors and agents.\r\n                        </li>\r\n                      </ul>\r\n                    </li>\r\n                    <li>\r\n                    The screenwriter waives all rights to your screenplay, so you maintain full ownership of your story.\r\n                    </li>\r\n                </ul>\r\n                <p><i>Please Note: Hollywood Treatment is a prerequisite for Hollywood Screenplay. Please speak with a marketing consultant if you have not yet purchased our Hollywood Treatment service for your book. Please <b>do not attempt to contact 5 More Minutes directly</b> or your project will immediately be removed from consideration.</i></p>\r\n                \r\n    <div class=\"about-5mm-block my-4\">\n  <div class=\"about-5mm-logo\">\n    <img src=\"/assets/img/5mm.png\" alt=\"5 More Minutes Logo\" />\n  </div>\n  <div class=\"about-5mm-content\">\n    <h3>About 5 More Minutes</h3>\n    <p>\n      5 More Minutes is a full-service production shingle run by veteran Hollywood executive John Sacchi. Sacchi has spent over two decades in the entertainment industry. Before founding 5 More Minutes, Sacchi spent 15 years as a senior production and development executive at Lionsgate Films where he oversaw films including Confidence, Employee of the Month, They Came Together, My Bloody Valentine, The Possession, Killers, The Last Stand, Addicted, Conan the Barbarian, Punisher, My Best Friend’s Girl, Pride, and Akeelah and the Bee. Some of the current projects 5 More Minutes is developing include an English language remake of <i>Instructions not Included</i>, directed by Anne Fletcher for Lionsgate; <i>Vanish Man</i> directed by Lee Toland Krieger and co-produced for 21 Laps and Lionsgate; <i>Dork Diaries</i>, which is based on the New York Times best selling children's book series and produced for Lionsgate; and the New York Times best selling author's <i>Rogues Gallery</i>, which is being produced for Lionsgate Television.\n    </p>\n  </div>\n</div>\n  </div>\n</div>",
  "sem-1000-clicks": "<div class=\"sem-1000-clicks-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>\r\n            The digital age has brought more than just innovation—it also gives you the convenience of sending a message in just a few seconds. This is why more and more marketers have taken their promotions to the biggest web player of them all—Google.\r\n        </p>         \r\n          <p>\r\n            With our SEM service, you can attract potential readers and drive traffic to your website with the help of this internet giant. An ad, which you can link to your website, will be strategically placed on Google’s search pages when they key in words and phrases related to your book.\r\n        </p>\r\n        <p>\r\n            Remember, everything is measured by a click. When your campaign is complete, we will provide you with a detailed report of how each keyword performed and the traffic generated from each. With this information, you can determine the best keywords to use in future campaigns.\r\n        </p>\r\n        <p>Whether you want to test the waters or generate a veritable flood of visitors, we have you covered. Drive a guaranteed number of visitors to the website of your choice with Omni's Basic Search Marketing.</p>\r\n        <ul>\r\n            <li>\r\n                1,000 clicks - $999, choose up to 20 keywords\r\n            </li>\r\n        </ul>\n  </div>\n</div>",
  "social-media-30-day-content-plan": "<div class=\"social-media-30-day-content-plan-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>\r\n          Ready to ignite a dynamic conversation about your book's release? Our 30-Day Social Media Content Schedule comes complete with all you require for a unified, powerful online presence that commands attention and encourages reader interaction. This is especially crafted for authors aiming to make a profound impact, featuring not just a Social Media Strategy but also turnkey social media collateral for each day up to your big launch—featuring graphics, captions, and much more, all optimized for enhanced reach and engagement.\r\n        </p>         \r\n          <p>\r\n            The Social Media Content Plan Includes:\r\n        </p>\r\n        \r\n        <ul>\r\n            <li>\r\n             <b> Weekly Goals:</b> Strategically scheduled each week to dovetail with your promotional calendar, cultivating awareness and piquing curiosity leading up to the release.\r\n            </li>\r\n            <li>\r\n              <b> Daily Visuals and Graphics:</b> Receive professionally designed graphics customized daily for the full 30 days, capturing the essence of your book’s branding and appealing directly to your audience.\r\n            </li>\r\n            <li>\r\n               <b> Engaging Captions:</b> Crafting post descriptions is no longer a challenge. We provide captions made to invite interaction, stir interest, and foster a connection, including intuitive calls-to-action to accompany your images.\r\n            </li>\r\n            <li>\r\n                <b>Book Snippets and Teasers:</b> Highlight the most enticing segments of your book with our selection help, paired with striking visuals designed to grab attention.\r\n            </li>\r\n            <li>\r\n              <b>  Hashtag Selection and Caption Guidance:</b> Widen your book’s exposure with curated hashtags and gain authenticity with our caption suggestions, helping you personalize each post.\r\n            </li>\r\n            <li>\r\n               <b> Engagement Methods:</b> We offer not only content but also strategies for engagement, suggesting conversational prompts to nurture a formidable, responsive community around your book.\r\n            </li>\r\n        </ul>\r\n        <p><b>Why Choose Our Comprehensive 30-Day Social Media Content Schedule?</b></p>\r\n\r\n        <p>Building a social media identity that encapsulates the value of your book demands both time and expertise. Our 30-Day Social Media Content Schedule removes the complex planning, providing you with ready-made content and the know-how to let you concentrate on your passion—writing. This service is perfect for authors who aspire to a professional-grade social media facade without the labor of starting from the ground up.</p>\r\n\r\n        <p>Leverage our expertise to turn your book launch into a powerful social campaign that not only lures readers but also stimulates interactions. With this 30-Day Plan, step into the social media scene fully equipped and prepared to make a powerful debut.</p>\r\n\r\n        <p>To explore longer-term strategies, speak with your Marketing Consultant regarding our 60- and 90-day expanded plans.</p>\r\n        <p>\r\n            *Note: this service does not cover actual posting or management of your social media accounts.\r\n        </p>\n  </div>\n</div>",
  "social-media-30-day-strategy": "<div class=\"social-media-30-day-strategy-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p><b>Elevate Your Book's Online Presence</b></p>\r\n          <p>\r\n            Maximize the impact and visibility of your book with our 30-Day Social Media Strategy. Tailored to ensure a seamless book launch, this guide provides a step-by-step weekly plan, rich with creative content suggestions, strategic hashtags, and specific goals designed to attract, engage, and resonate with your target readership.\r\n        </p>     \r\n        \r\n        <p>Ideal for authors of any caliber, whether you're launching your first novel, injecting new life into a non-fiction masterpiece, or unveiling an exciting sequel, our strategy comprehensively equips you to grab your audience's attention across various social media platforms.</p>        \r\n            <p><b>Features Include:</b></p>\r\n        <ul>\r\n            <li>\r\n             <b> Targeted Weekly Goals</b>: Every week brings a targeted aim that complements your launch schedule, setting a pace for generating anticipation early on and intensifying interest as your release date nears.\r\n            </li>\r\n            <li>\r\n               <b> Daily Content Ideas:</b> Take the guesswork out of daily postings with individually crafted content ideas that showcase the heart of your book's themes, aiding in accelerating momentum and stimulating follower interaction.\r\n            </li>\r\n            <li>\r\n                <b>Hashtag Guidance: </b>Broaden your reach with our bespoke list of hashtags, tailored to draw an audience intrinsically interested in your book's genre and core message.\r\n            </li>\r\n            <li>\r\n               <b> Engagement Techniques:</b> In the realm of social media, meaningful connections are key. Our guide includes sage advice on stirring up conversations, captivating your followers, and converting passing interest into a devoted fan base.\r\n            </li>\r\n        </ul>\r\n        <p>\r\n            <b>Why Opt for the 30-Day Social Media Strategy?</b>\r\n        </p>\r\n\r\n        <p>Book releases are significant milestones that demand smart, engaging online strategies. The 30-Day Social Media Strategy is your solution for creating and maintaining a magnetic social presence. We provide you with an easy-to-navigate content calendar that reflects the latest social media trends for maximum effect.</p>\r\n\r\n        <p>Embark on your book launch journey supported by a strategy that not only stirs excitement and captivates interest but solidifies your work as a sought-after reading adventure. With our 30-Day Social Media Launch Plan, tackle the digital landscape with confidence and flair.</p>\r\n\r\n        <p>Interested in ongoing support? Inquire about our extended 60- and 90-day packages with your Marketing Consultant.</p>\r\n        <p>*Note: The creation of content and graphical design for individual posts is not included in this service.</p>\n  </div>\n</div>",
  "kirkus-title-express": "<div class=\"kirkus-title-express-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>Do you want to establish an online presence for your book and attract a following?</p>\r\n          <p>\r\n            A book giveaway is a good place to start, because this gives you the chance to personally find like-minded readers and even boost your reputation. Now, imagine if you can have your own giveaway online. You won't just find potential readers in your area, but quite possibly around the world too!\r\n        </p>     \r\n        <p>Collaborating with a revered publishing name like the Kirkus Reviews should be able to help you have a successful online giveaway. With our Kirkus Title Express, you wouldn't even need to start your own book giveaway from scratch because your book will be included in Kirkus' organized online book giveaway. This giveaway will be promoted around the Kirkus website and will be advertised in their newsletter.</p>\r\n        \r\n            <p><b>With this service, you get:</b></p>\r\n        <ul>\r\n            <li>\r\n             <b> A two-week online giveaway.</b> Your book will be listed in one of Kirkus’s Online Giveaways.\r\n            </li>\r\n            <li>\r\n               <b>100 digital BookStub™ codes to be given away.</b> The digital BookStub™ codes offer a link to a one-time downloadable free copy of your e-book.\r\n            </li>\r\n            <li>\r\n                <b>A standard side box ad announcing the giveaway.</b>It will be placed on Kirkus.com’s homepage and on one issue of Kirkus’ eNewsletters, Critic’s Picks. The ad redirects to Kirkus’s online giveaway page where your book will be displayed along with other works. The side box ad will also have information about the giveaway that should be able to encourage visitors to get a free sample copy of your book.\r\n            </li>\r\n\r\n        </ul>\r\n        <p>\r\n            <b>More About I Kirkus Title Express</b>\r\n        </p>\r\n\r\n        <p>Kirkus Reviews was founded in 1933 and continues to be an authoritative voice in book discovery. As of 2019, Kirkus reviews 10,000 books per year, garners an average of 2.6 million website impressions per month, and fosters 65,000 email newsletter subscribers.</p>\n  </div>\n</div>",
  "online-booksellers-advertising": "<div class=\"online-booksellers-advertising-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>If you want to cover a lot of book-marketing ground, advertise on websites that are both popular and specialized. With our Online Booksellers Advertising service, you can do just that.</p>\r\n       \r\n           <p>We will put up your book ad on two of the industry’s most reliable websites: Amazon and Ingram.</p>\r\n\r\n           <p>\r\n            <b>Amazon</b> is one of the world’s largest online retailers with 181 million unique visitors in a month. More US consumers start their web searches on Amazon over anywhere else. Amazon is available in 14 countries.\r\n           </p>\r\n\r\n           <p><b>Ingram’s ipage</b> is an easy-to-use online search and book-ordering platform used by over 50,000 retailers, librarians, and educators around the globe. The website has 13,000 unique visitors daily.</p>\r\n\r\n           <p><b>Here’s how your book will be advertised on these sites:</b></p>\r\n           <ul>\r\n            <li>\r\n                <b>Banner ad campaign on Amazon:</b> Feature your book cover in a banner ad promoted on Amazon (500,000 guaranteed impressions).</li>\r\n                <li>\r\n                    <b>Banner ad campaign on Ingram’s ipage:</b> Feature your book cover on a special landing page with twenty-three other titles. For two weeks, ipage will display a banner ad promoting this landing page. Since ipage is a go-to source for complete title information, you have the opportunity to reach retailers and librarians where they work daily.\r\n                </li>\r\n           </ul>\r\n           <p><i>This service is best for books available in both ebook and paperback. The book must also be listed as returnable in Ingram.</i></p>\n  </div>\n</div>",
  "e-book-promo-venture-30-days": "<div class=\"e-book-promo-venture-30-days-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>As a reader, you might already know the allure of book sales and bargain bookstores. There’s nothing like coming across a great book at a discounted price—whether it’s a bestseller or a new yet intriguing title.</p>\r\n\r\n           <p>So why not attract potential readers for your book in the same way? Tap into the excitement that comes with bargains through our <b>E-book Promotion service</b>.</p>\r\n\r\n\r\n           <p>\r\n            Here’s how it works: We will mark down the retail price of your Kindle book to 99ȼ on Amazon for a set period. And to get the word out about this special deal, we will advertise your book through banner ads on these two popular online platforms:\r\n           </p>\r\n\r\n           <ul>\r\n            <li>\r\n                <b>BookBub</b>, a daily email blast that champions ebook discovery, notifying 62.4 million subscribers* about deals on handpicked recommendations as well as updates from their favorite authors; and\r\n            </li>\r\n            <li>\r\n                <b>Facebook</b>, the most popular social media platform, with 1.5 billion users worldwide visiting the site on a daily basis.*\r\n            </li>\r\n           </ul>\r\n\r\n           <p>The <b>E-book Promo Venture – 30 days</b> service includes:</p>\r\n           <ul>\r\n            <li>Limited-time price change of your Kindle book to 99ȼ</li>\r\n            <li>\r\n                Placement of your book ad on BookBub’s daily email blasts for 30 days. See sample here\r\n            </li>\r\n            <li>\r\n                Your e-book promo, along with seven others in the same genre category, will be advertised on Facebook for 30 days. See sample here\r\n            </li>\r\n           </ul>\r\n\r\n           <p>Make your Kindle book more attractive to potential readers. Contact your Omni representative to learn more about this service or to sign up.</p>\r\n\r\n           <p><i>*As of 2018</i></p>\n  </div>\n</div>",
  "e-book-promo-launcher": "<div class=\"e-book-promo-launcher-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>As a reader, you might already know the allure of book sales and bargain bookstores. There’s nothing like coming across a great book at a discounted price—whether it’s a bestseller or a new yet intriguing title.</p>\r\n\r\n           <p>So why not attract potential readers for your book in the same way? Tap into the excitement that comes with bargains through our <b>E-book Promotion</b> service.</p>\r\n\r\n           <p>Here’s how it works: We will mark down the retail price of your Kindle book to 99ȼ on Amazon for a set period. And to get the word out about this special deal, we will advertise your book through banner ads on these three popular online platforms:</p>\r\n\r\n           <ul>\r\n            <li>\r\n                <b>BookBub</b>, a daily email blast that champions ebook discovery, notifying 62.4 million subscribers* about deals on handpicked recommendations as well as updates from their favorite authors;\r\n            </li>\r\n            <li>\r\n                <b>Facebook</b>, the most popular social media platform, with 1.5 billion users worldwide visiting the site on a daily basis;* and\r\n            </li>\r\n            <li>\r\n                <b>Amazon</b>, the largest e-commerce company in the world.*\r\n            </li>\r\n           </ul>\r\n\r\n           <p>The <b>E-book Promo Launcher – 30 days</b> service includes:</p>\r\n\r\n           <ul>\r\n            <li>\r\n                Limited-time price change of your Kindle book to 99ȼ\r\n            </li>\r\n            <li>\r\n                Placement of your book ad on BookBub’s daily email blasts for 30 days. See sample here\r\n            </li>\r\n            <li>\r\n                Your book ad, along with seven others in the same genre category, on Facebook for 30 days. See sample here\r\n            </li>\r\n            <li>\r\n                Your book ad on amazon.com for 30 days. <br>\r\n                Sample 1\r\n                Sample 2\r\n                Sample 3\r\n            </li>\r\n           </ul>\r\n\r\n           <p><i>\r\n            *As of 2018 <br>\r\n            **Statista, 2020 <br>\r\n            *** Promo price is in US currency and will be available on Amazon only <br>\r\n           </i></p>\n  </div>\n</div>",
  "social-media-advertising-basic": "<div class=\"social-media-advertising-basic-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>With its huge user database, Facebook has the traffic to help give your book’s marketing campaign some traction. Even Instagram, another social media website owned by Facebook, is a viable marketing platform that is used by many brands. However, to effectively promote your work, you must cut through the online clutter and put your book in front of an audience interested in your book.</p>\r\n\r\n         <p>Don’t know how to start? Omni can help with the <b>Social Media Advertising Basic package</b>. Here’s how it works:</p>\r\n\r\n         <ul>\r\n            <li>\r\n                We will create a custom audience that specifically targets potential readers who might be interested in your book.\r\n            </li>\r\n            <li>\r\n                An image ad of your book will be shown at least <b>a million times</b> on Facebook and Instagram’s news feeds. Note: Instagram ads appear on mobile only. See sample here\r\n            </li>\r\n            <li>\r\n                We will monitor and manage your ad campaign.\r\n            </li>\r\n         </ul>\r\n\r\n         <p>Note: Facebook retains the right to decline to show ads based on their own policies and practices.</p>\r\n\r\n         <h3 style=\"color: green;\"> <b>More About | Social Media Advertising Basic</b> </h3>\r\n         <p>Facebook is the most popular social media platform. 76 percent of Facebook users visit the website on a daily basis—averaging eight sessions in a day. In the U.S., 68 percent of adults use Facebook. Instagram has the second highest user engagement, next only to Facebook.</p>\n  </div>\n</div>",
  "social-media-advertising-essential": "<div class=\"social-media-advertising-essential-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>With its huge user database, Facebook has the traffic to help give your book’s marketing campaign some traction. Even Instagram, another social media website owned by Facebook, is a viable marketing platform that is used by many brands. However, to effectively promote your work, you must cut through the online clutter and put your book in front of an audience interested in your book.</p>\r\n         \r\n            <p>Don’t know how to start? Omni can help with the <b>Social Media Advertising Essential package.</b> Here’s how it works:</p>\r\n\r\n         <ul>\r\n            <li>\r\n               We will create a custom audience that specifically targets potential readers who might be interested in your book.\r\n            </li>\r\n            <li>\r\n               An image ad and a short video ad for your book will be shown <b>at least 2 million times</b> on Facebook and Instagram’s news feeds. Note: Instagram ads appear on mobile only. Click these links for a sample of the image and video ads. \r\n            </li>\r\n            <li>\r\n                We will monitor and manage your ad campaign.\r\n            </li>\r\n         </ul>\r\n\r\n         <p>Note: Facebook retains the right to decline to show ads based on their own policies and practices.</p>\r\n\r\n         <h3 style=\"color: green;\"> <b>More About | Social Media Advertising Basic</b> </h3>\r\n         <p>Facebook is the most popular social media platform. 76 percent of Facebook users visit the website on a daily basis—averaging eight sessions in a day. In the U.S., 68 percent of adults use Facebook. Instagram has the second highest user engagement, next only to Facebook.</p>\n  </div>\n</div>",
  "social-media-advertising-advanced": "<div class=\"social-media-advertising-advanced-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>With its huge user database, Facebook has the traffic to help give your book’s marketing campaign some traction. Even Instagram, another social media website owned by Facebook, is a viable marketing platform that is used by many brands. However, to effectively promote your work, you must cut through the online clutter and put your book in front of an audience interested in your book.</p>\r\n         \r\n            <p>Don’t know how to start? Omni can help with the <b>Social Media Advertising Essential package.</b> Here’s how it works:</p>\r\n\r\n         <ul>\r\n            <li>\r\n               We will create a custom audience that specifically targets potential readers who might be interested in your book.\r\n            </li>\r\n            <li>\r\n             An image ad, a short video ad, and an interactive mobile ad will be shown <b>at least 4 million times</b> on Facebook and Instagram’s news feeds and on Facebook’s audience network of mobile apps. Note: Instagram ads appear on mobile only. Click these links for a sample of the image , video, and mobile ads. \r\n            </li>\r\n            <li>\r\n                We will monitor and manage your ad campaign.\r\n            </li>\r\n         </ul>\r\n\r\n         <p>Note: Facebook retains the right to decline to show ads based on their own policies and practices.</p>\r\n\r\n         <h3 style=\"color: green;\"> <b>More About | Social Media Advertising Basic</b> </h3>\r\n         <p>Facebook is the most popular social media platform. 76 percent of Facebook users visit the website on a daily basis—averaging eight sessions in a day. In the U.S., 68 percent of adults use Facebook. Instagram has the second highest user engagement, next only to Facebook.</p>\n  </div>\n</div>",
  "display-advertising-on-google-30-days-package": "<div class=\"display-advertising-on-google-30-days-package-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>Consumers, including book buyers, are especially active online, spending 95% of their time interacting and checking out websites and content that interest them. With the Display Advertising on Google services, you can engage potential readers by putting your book advertisement right in front of them on their very screens.</p>\r\n        <p>When you sign up for an Omni Display Advertising on Google service, your book’s ad will be strategically placed on up to 2 million Google Display Network partner websites, including Google-owned websites such as Google Finance, Gmail, Blogger, and YouTube.</p>\r\n          <p>Alternatively, you can identify which sites to run your book ads on using very specific demographic parameters like location, age, language, audience interest, topic, keywords, and even specific websites that are part of Google’s network.</p>\r\n\r\n          <p>This service includes:</p>\r\n\r\n          <ul>\r\n            <li>Choice of ad format: image with text, text only, or both</li>\r\n            <li>30-day book advertising placement on targeted Google websites and partner-websites on the Google Display Network</li>\r\n              <li>Up to 10 GB of excess bandwidth per month when you use your existing Omni-designed website as a landing page</li>\r\n          </ul>\r\n\r\n          <p><strong>Note: </strong>You may place your book ad on a selection of targeted Google websites available to you. Signing up for this service allows you to choose by location, age, language, audience interest, topic, keywords, and even specific websites that are part of Google’s network, but you may not present your own list of websites.</p>\n  </div>\n</div>",
  "sem-advanced-campaign": "<div class=\"sem-advanced-campaign-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>With millions of Google searches made every minute, you should take the chance of spreading word about your book with the help of this internet giant too.</p>\r\n       <p>Harness the power of Google with our SEM – Advanced Campaign service. With premium ad placement, and a long-term campaign, optimized search marketing with Omni can help your readers discover your book on their Google search pages. Plus, we will design a website where interested parties will first visit when they click on your ad.</p>\r\n       <p>What you get:</p>\r\n       \r\n       <ul>\r\n        <li><strong>Online Ad Presence for 3 Months.</strong> Reach more people and grow your readership with 3 months of premium, targeted ads on Google.</li>\r\n        <li><strong>First page placement of your ad over the campaign period.</strong> Think about it: When was the last time you clicked all the way to page 6 on your Google search page? With this service, your ad will show up on the first page search results.</li>\r\n        <li><strong>In-house search experts to help you choose up to 30 keywords.</strong> Keywords are the words and/or phrases people use to find content on search engines. The right keywords help you show up on relevant searches, meaning your target audience can find your website—and your book—that much faster. Keyword performance is tracked and managed monthly so only high-performing keywords and phrases are retained.</li>\r\n        <li><strong>Monthly reporting and ability to change campaign details proactively.</strong> We’ll keep track and make monthly reports of how well your campaign is doing so we can change our search engine marketing strategy as necessary, with you right at the helm of the whole operation.</li>\r\n        <li><strong>Deluxe Website Setup. </strong>Your website is your portfolio, your resume, your brand, and your own digital storefront all in one, so it’s crucial to leave a great first impression on visitors with a well-designed website.</li>\r\n      \r\n      </ul>\n  </div>\n</div>",
  "sem-specialist-campaign": "<div class=\"sem-specialist-campaign-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>With millions of Google searches made every minute, you should take the chance of spreading word about your book with the help of this internet giant too.</p>\r\n        <p>Harness the power of Google with our SEM – Specialist Campaign service. With premium ad placement, and a long-term campaign, optimized search marketing with Omni can help your readers discover your book on their Google search pages. Plus, we will design a website where interested parties will first visit when they click on your ad.</p>\r\n        <p>What you get:</p>\r\n        <ul>\r\n          <li><strong>Ad Presence for 5 Months.</strong> Reach more people and grow your readership with 5 months of premium, targeted ads on Google.</li>\r\n            <li><strong>First page placement of your ad over campaign period. </strong>Think about it: When was the last time you clicked all the way to page 6 on your Google search page? With this service, your ad will show up on the first page search results.</li>\r\n              <li><strong>In-house search experts to assist you in choosing up to 50 keywords.</strong> Keywords are the words and/or phrases people use to find content on search engines. The right keywords help you show up on relevant searches, meaning your target audience can find your website—and your book—that much faster. Keyword performance is tracked and managed monthly so only high-performing keywords and phrases are retained.</li>\r\n                <li><strong>Bi-weekly reporting and ability to change campaign details proactively.</strong> We’ll keep track and make reports every two weeks of how well your campaign is doing so we can change our search engine marketing strategy as necessary, with you right at the helm of the whole operation.</li>\r\n                  <li><strong>Website Design – Premier Service with blog page. </strong>Your website is your portfolio, your resume, your brand, and your own digital storefront all in one, so it’s crucial to leave a great first impression on visitors with a well-designed website. We’ll help you set up your own blog, too, where you can keep your readers up to date on all your thoughts and latest projects.</li>\r\n\r\n        </ul>\n  </div>\n</div>",
  "author-website-setup": "<div class=\"author-website-setup-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>Reach out to a worldwide audience with Omni's Author Website Setup service.</p>\r\n          <p>Having a personal website means that you can be viewed by anyone, anywhere in the world, 24 hours a day, 365 days of the year - as long as they have Internet access. It is one of the truly efficient ways of marketing your work. With your own website, millions around the world will know about you and your books; you can link your website to forge stronger business relationships with online bookstores, book clubs and author organizations; you can practically level the literary playing field with the more established authors; the possibilities, it goes without saying, are endless.</p>\r\n          <p>You can choose to have as many as 10 pages created for your website. No matter how many pages you choose, we will take care of your website’s HTML creative design and content.</p>\r\n          <p>What’s more, the domain name registration and web hosting fulfillment are FREE for a whole year.</p>\r\n          <p>Our web designers will start creating your website based on the following guidelines:</p>\r\n\r\n          <div class=\"table-responsive my-4\"><table class=\"table table-bordered mb-0\" style=\"border-color: #ebd9c4; font-size: 0.92rem;\">\r\n            <thead style=\"background-color: #fbf7f2;\">\r\n                <tr>\r\n                    <th>Features</th>\r\n                    <th>3 Pages<br>$399</th>\r\n                    <th>6 Pages<br>$599</th>\r\n                    <th>10 Pages<br>$999</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                <tr>\r\n                    <td>Max Number of Pages</td>\r\n                    <td>3</td>\r\n                    <td>6</td>\r\n                    <td>10</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Number of Images</td>\r\n                    <td>2</td>\r\n                    <td>10</td>\r\n                    <td>up to 60 MB</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Email Account</td>\r\n                    <td>1</td>\r\n                    <td>2</td>\r\n                    <td>3</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Rotating Headers</td>\r\n                    <td>No</td>\r\n                    <td>2</td>\r\n                    <td>4</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Domain Name*</td>\r\n                    <td>1 year</td>\r\n                    <td>1 year</td>\r\n                    <td>1 year</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Basic Web Hosting</td>\r\n                    <td>1 year</td>\r\n                    <td>1 year</td>\r\n                    <td>1 year</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Animated Images on Content Area</td>\r\n                    <td></td>\r\n                    <td>1</td>\r\n                    <td>2</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Contact Form</td>\r\n                    <td>Optional</td>\r\n                    <td>Optional</td>\r\n                    <td>Optional</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Animated Book Excerpt</td>\r\n                    <td></td>\r\n                    <td></td>\r\n                    <td>Optional</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Flash Header Design</td>\r\n                    <td></td>\r\n                    <td></td>\r\n                    <td>Optional</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Gallery</td>\r\n                    <td></td>\r\n                    <td></td>\r\n                    <td></td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Events Page Content Managed by Author</td>\r\n                    <td></td>\r\n                    <td></td>\r\n                    <td></td>\r\n                </tr>\r\n            </tbody>\r\n        \r\n          <thead style=\"background-color: #fbf7f2;\">\r\n              <tr>\r\n                  <th>Page Choices</th>\r\n                 \r\n              </tr>\r\n          </thead>\r\n          <tbody>\r\n              <tr>\r\n                  <td>Home</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n              </tr>\r\n              <tr>\r\n                  <td>About the Book</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n              </tr>\r\n              <tr>\r\n                  <td>About the Author</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n              </tr>\r\n              <tr>\r\n                  <td>Order Page</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n              </tr>\r\n              <tr>\r\n                  <td>Excerpt</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n              </tr>\r\n              <tr>\r\n                  <td>Contact Page</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n              </tr>\r\n              <tr>\r\n                  <td>Gallery</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n              </tr>\r\n              <tr>\r\n                  <td>Reviews</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n              </tr>\r\n              <tr>\r\n                  <td>Blog Page</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n              </tr>\r\n              <tr>\r\n                  <td>Other Works Media and Events</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n                  <td>✔</td>\r\n              </tr>\r\n          </tbody>\r\n      \r\n        <thead style=\"background-color: #fbf7f2;\">\r\n            <tr>\r\n                <th>SEO Inclusions</th>\r\n                <th></th>\r\n                <th></th>\r\n                <th></th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n            <tr>\r\n                <td>Title Tag Creation</td>\r\n                <td>Yes</td>\r\n                <td>Yes</td>\r\n                <td>Yes</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Content Creation (Home Page / Index Only)</td>\r\n                <td>Yes</td>\r\n                <td>Yes</td>\r\n                <td>Yes</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Meta Description Creation</td>\r\n                <td>Yes</td>\r\n                <td>Yes</td>\r\n                <td>Yes</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Google Mobile-Friendly Test (WordPress Update)</td>\r\n                <td>Yes</td>\r\n                <td>Yes</td>\r\n                <td>Yes</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Keywords Creation</td>\r\n                <td></td>\r\n                <td>up to 5</td>\r\n                <td>up to 10</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Submission to Google Search Engine (Google Index)</td>\r\n                <td></td>\r\n                <td>Yes</td>\r\n                <td>Yes</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Google Sitemap Creation and Submission</td>\r\n                <td></td>\r\n                <td></td>\r\n                <td>Yes</td>\r\n            </tr>\r\n            <tr>\r\n                <td>Custom Favicon</td>\r\n                <td></td>\r\n                <td></td>\r\n                <td>Yes</td>\r\n            </tr>\r\n        </tbody>\r\n    </table></div>\r\n    <div class=\"table-responsive my-4\"><table class=\"table table-bordered mb-0\" style=\"border-color: #ebd9c4; font-size: 0.92rem;\">\r\n      <thead style=\"background-color: #fbf7f2;\">\r\n          <tr>\r\n              <th>Additional Services</th>\r\n              <th>Details</th>\r\n          </tr>\r\n      </thead>\r\n      <tbody>\r\n          <tr>\r\n              <td>Domain Name registration and Web Hosting**</td>\r\n              <td>$129 per year</td>\r\n          </tr>\r\n          <tr>\r\n              <td>Country-specific Domain Name Add-on</td>\r\n              <td>$60 per year</td>\r\n          </tr>\r\n          <tr>\r\n              <td>Country-specific Domain Name Registration & Web Hosting</td>\r\n              <td>$249 per year</td>\r\n          </tr>\r\n          <tr>\r\n              <td>Additional page</td>\r\n              <td>$40 per page</td>\r\n          </tr>\r\n          <tr>\r\n              <td>Bandwidth Excess***</td>\r\n              <td>40</td>\r\n          </tr>\r\n          <tr>\r\n              <td>Additional image scanned and prepared for the web</td>\r\n              <td>$12 per photo</td>\r\n          </tr>\r\n          <tr>\r\n              <td>Site Maintenance*</td>\r\n              <td></td>\r\n          </tr>\r\n          <tr>\r\n              <td>- alterations on page (design and copy)</td>\r\n              <td>$65/hour, billable in 15-minute increments</td>\r\n          </tr>\r\n          <tr>\r\n              <td>- changing graphics on existing pages</td>\r\n              <td>$65/hour, billable in 15-minute increments</td>\r\n          </tr>\r\n      </tbody>\r\n  </table></div>\r\n\r\n\r\n  <h2>Okay! How do I sign up?</h2>\r\n  <p>We will fill you in on the phone and send you a product sheet and order form. Then simply choose your service level, fill out the order form, and return it to us by email, fax, or mail. You can even complete your order on the phone. By filling out the order form, you can tell us vital information about yourself and your book, and about your target market.</p>\r\n  <p>For a more personalized touch, we suggest you include your photo and images of your book cover/s. We also encourage you to do a write-up for your site, although a copywriter is also available for those who prefer full content management service. Sending at least 2 or more images to enhance the artistic rendition of your website also helps to enhance the visual feel.*</p>\r\n    <p>*Please note that the absence of these materials may cause a delay in fulfillment.</p>\r\n    <p>You can also make suggestions for your domain name, though only one will be registered upon your approval. This, of course, depends on the domain name’s availability.</p>\r\n  <p>REMINDER: Orders are scheduled on a first-come, first-served basis.</p>\n  </div>\n</div>",
  "press-release-essential-edition": "<div class=\"press-release-essential-edition-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>When done right, a press release is an effective way to get publicity. The Omni Press Release – Essential Edition helps you grab the media’s attention by promoting your book with an expertly crafted press release. Prepared in a format to pique editors' interest in your book, your press release is delivered to numerous media outlets, creating the potential for increased coverage of you and your book. More coverage equals more exposure for your title.</p>\r\n            <p><strong>The Press Release – Essential Edition includes:</strong></p>\r\n\r\n            <ul>\r\n              <li>Customized one-page press release based on information you provide about your book</li>\r\n              <li>Delivery of your press release to a minimum of 500 media outlets chosen based on location, your book’s genre and more; recipients may include magazines, newspapers, online publications, and radio and TV programs</li>\r\n              <li>Press release tracking for one month through Meltwater's powerful PR platform</li>\r\n            </ul>\r\n\r\n            <p>View a press release sample.</p>\r\n            <p><strong>About Meltwater</strong>\r\n              Meltwater was founded in 2001 as the world’s first online media monitoring company. Today, Meltwater is a global leader in media intelligence and social analytics, helping to bridge the gap between Public Relations, Communications and Marketing departments with an intuitive, all-in-one solution powered by AI-driven insights. Over 30,000 of the world’s most respected brands rely on Meltwater to help inform their strategic decision-making, and with over 55 offices across six continents.</p>\n  </div>\n</div>",
  "press-release-web-optimized-edition": "<div class=\"press-release-web-optimized-edition-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>With a web-optimized press release, anyone who conducts a web search of you or your book can find you much easier, including members of the press. The Omni <strong>Press Release – Web-Optimized Edition</strong> is professionally crafted to include keywords that increase your release’s chances of being returned as a higher ranking search engine result. The easier your release is to find, the more likely you are to get promotional coverage for your book.</p>\r\n            <p><strong>Press Release - Web-Optimized Edition includes:</strong></p>\r\n\r\n            <ul>\r\n              <li>A professional writer crafts your press release and includes keywords to optimize it for search engine results, so that your release has a better chance of being found and read</li>\r\n              <li>Omni distributes the press release to as many as 30,000 opt-in journalists and more than 250,000 news subscribers through our newswire service partner, PRWeb. While we cannot guarantee which websites will display your press release, our distributed press releases commonly appear on websites such as Google News, Yahoo News and other websites where journalists search daily for relevant news and topics for story ideas.</li>\r\n              <li>Press-release tracking for one month</li>\r\n              <li>Activity feedback so you can track the effectiveness of your web-optimized press release</li>\r\n\r\n            </ul>\r\n\r\n              <p>View a web-optimized press release sample.</p>\r\n              <p></p>\n  </div>\n</div>",
  "radio-book-talk": "<div class=\"radio-book-talk-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>You'll never run out of places to talk about books. There are cafés, libraries, bookstores, and you can even chat about it on the radio. As an author, you can use the airwaves not only to talk about what you love, but it's where you can promote your book to interested listeners as well.</p>\r\n          <p>With our Radio Book Talk service, you’ll get both online and terrestrial radio coverage: talk about your book on a radio show hosted by Kate Delaney, an Emmy award-winning broadcaster, and get interviewed on WebTalkRadio’s Books on Air.  Plus, your book will be announced to the avid listeners of Newsgram, a show that talks about trends and popular recommendations.</p>\r\n          <p>Radio Book Talk is highly recommended for literary novels, nonfiction books like self-help, memoirs, and business books.</p>\r\n\r\n          <p><strong>This service includes:</strong></p>\r\n\r\n          <ul>\r\n            <li>An 8 to 12-minute interview On America Tonight with Emmy-award winning host, Kate Delaney.  America Tonight airs on approximately 100 stations across the US.  The author will receive a mp3 file after the interview. </li>\r\n            <li>A 15-minute in-depth online interview on Books on Air with Suzanne Harris. This will also be distributed to Apple, iHeart Radio, Spotify and other podcast aggregators.</li>\r\n            <li>Your book featured on WebTalkRadio’s Newsgram show. It will also be distributed to Apple, iHeart Radio, Spotify and other podcast aggregators.</li>\r\n         \r\n\r\n                  <p><strong>Sample Newsgram Feature: </strong></p>\r\n\r\n                  <audio controls class=\"w-100 my-2\" style=\"max-width: 480px; height: 42px;\">\r\n                    <source src=\"/assets/audio/Newsgram_Nevsah.mp3\" type=\"audio/mpeg\">\r\n                    Your browser does not support the audio element.\r\n                </audio>\r\n\r\n                <li>A digital copy of the radio interviews that you can use in all of your marketing activities.</li>\r\n           </ul>\r\n\r\n           <p><strong>More About Kate Delaney, America Tonight, and WebTalkRadio</strong></p>\r\n\r\n           <p><strong>Kate Delaney</strong><br> \r\n            Kate Delaney is an award-winning and respected national presenter. She has been in the radio and television industry for 20 years and has interviewed over 16,000 people. She garnered a Television Emmy for her special report on the AIDS epidemic in New Mexico, and as well as several Golden Mics for a series on immigration.</p>\r\n\r\n            <p><strong>America Tonight</strong><br>\r\n            America Tonight with Kate Delaney airs Monday through Saturday from Washington, D.C.  and reaches around 2.9 million listeners.</p>\r\n\r\n            <p><strong>WebTalkRadio</strong><br>\r\n              WebTalkRadio is run by established radio and podcasting professionals, and has produced award-winning radio shows. Currently, it has also created content for terrestrial radio, and YouTube. Books on Air and Newsgram are just some of the programs run by WebTalkRadio.</p>\r\n\r\n            <p><strong>Books on Air</strong><br>\r\n              Books on Air is a platform where authors can share their creative process with readers everywhere. This show is hosted by Suzzane Harris. She’s an experienced media personality and an avid reader.</p>\r\n\r\n              <p><strong>Newsgram</strong><br>\r\n                Newsgram showcases the various trends and products—including books.  It aims to help its listeners keep up with the latest goings-on. This show is hosted by Sam Youmans, a seasoned newsroom personality. </p>\r\n\r\n                <p style=\"font-size: .9em;\">Note: Featured books are subject for approval. Certain genres, topics and themes may not be suitable for a terrestrial radio interview. </p>\n  </div>\n</div>",
  "audio-snip": "<div class=\"audio-snip-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>Thirty seconds may seem like an insignificant amount of time but that's not completely true, especially for authors like you. In half a minute, you can probably finish a simple writing exercise, make a working title, and even connect with your target readers.</p>\r\n            <p>Yes, you read that right. It's possible to reach out to your readers in such a short period of time. All you need to do is find the right marketing tool, like our Audio Snip service.</p>\r\n            <p>With this service, you get a 30-second audio teaser for your book that you can use to start or enhance your marketing campaign.</p>\r\n            <p><strong>The Audio Snip package includes:</strong></p>\r\n                <ul>\r\n                  <li>A 30-second professionally produced audio teaser about your published book, informing potential readers of its availability.</li>\r\n                </ul>\n  </div>\n</div>",
  "online-interview": "<div class=\"online-interview-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n<p>Position yourself as an expert on your book’s subject matter and put your voice on the radio. Whatever your reason, getting on the radio can give you a powerful marketing push. The Online Interview service is a strategic marketing tool to enhance your marketing plan. Times are evolving with the rise in popularity of iPods and satellite radio; listeners have more choices and more ways to access content than ever before, and streaming radio is an excellent way to reach new audiences. Plus, you can use your interview recording as a launch pad for your next big promotional push.</p>\r\n          <p>What you get:</p>\r\n\r\n\r\n            <ul>\r\n              <li>Recording of a 10- to 15-minute online radio interview completed over the phone</li>\r\n              <li>Your interview aired on one spot of our weekly Internet radio station, Omni Radio with J. Douglas Barker</li>\r\n              <ul>\r\n                <li>Omni Radio airs Saturdays at 3:00 p.m. CT (encore 11 p.m. CT on Thursdays)</li>\r\n                <li>Omni Radio 2 airs Saturdays at 1:00 p.m. CT (encore 1 p.m. CT on Sundays)</li>\r\n              </ul>\r\n              <li>Show is syndicated via iTunes and Toginet.com, and the interview is digitally retrievable for use on mobile devices (iPhone, iPad, etc.)</li>\r\n              <li>A digital copy of the radio interview for use in all of your marketing activities with unlimited rights to burn, distribute, play during speaking engagements, or post on your website, blog, e-mail or future promotions</li>\r\n              <li>Pre-show questionnaire and pre-show conversation with host J. Douglas Barker to cover topics</li>\r\n            </ul>\r\n\r\n            <p><strong>About the host:</strong></p>\r\n            <p>With a passion for “all things creative,” J. Douglas Barker is an accomplished actor, singer, and audio producer. He has over 35 years of studio excellence and can be heard worldwide through his current efforts as producer and talent for Toginet Radio Network. He also has voice actor credits in the CBS “Movie of the Week,” along with countless commercials and studio work for a variety of regional and national accounts (Disney Companies, Churches Chicken, United Technologies, and many others). J. Douglas is a longtime professional in broadcast consulting, public speaking, sales, and marketing, along with being a husband and father.</p>\r\n\r\n            <p>Never been interviewed for radio before? No problem; the interview will be fun and easy. J. Douglas Barker will guide you through a “warm up” chat minutes prior to your actual interview recording, and you will have the option to decide what topics and questions you will be comfortable with for the interview.</p>\n  </div>\n</div>",
  "set-your-own-price": "<div class=\"set-your-own-price-detail-content\">\n                      <div class=\"editorial-callout-notice p-3 mb-4 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                        <p class=\"fst-italic mb-0 fw-medium editable-field\" style=\"color: #57534e; font-size: 0.92rem;\" data-block-key=\"service.set-your-own-price.p1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                          Take control of your book's retail price and the royalties you earn. Set Your Own Price gives you the flexibility to adjust the retail price of the hardcover and paperback formats of your book.\n                        </p>\n                      </div>\n\n                      <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n                        <p class=\"mb-3 editable-field\" data-block-key=\"service.set-your-own-price.p2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                          Pricing is a fundamental component of book marketing. Whether your objective is to set an enticing promotional price to drive maximum unit sales or to establish a premium price point that yields higher royalties per copy, the Set Your Own Price service puts you in the driver’s seat.\n                        </p>\n\n                        <div class=\"p-3.5 mb-4 rounded-3\" style=\"background: #fdfaf5; border: 1px solid #ebd9c4;\">\n                          <h6 class=\"fw-bold mb-2\" style=\"color: #2b2219; font-size: 0.96rem;\">\n                            Key Benefits & Strategic Power:\n                          </h6>\n                          <ul class=\"mb-0 ps-3\" style=\"color: #57534e; font-size: 0.92rem; line-height: 1.75;\">\n                            <li class=\"editable-field\" data-block-key=\"service.set-your-own-price.li1\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                              <strong>Format Flexibility:</strong> Adjust the retail price of both hardcover and paperback editions of your title.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.set-your-own-price.li2\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                              <strong>Strategic Pricing Alignment:</strong> Position your title competitively within your genre against competing commercial releases.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.set-your-own-price.li3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                              <strong>Synergy with Author Advantage:</strong> Combine with the Author Advantage Royalty Program to set a competitive retail price while harvesting maximum royalty margins.\n                            </li>\n                            <li class=\"editable-field\" data-block-key=\"service.set-your-own-price.li4\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                              <strong>Full Distribution Synchronization:</strong> Price updates are distributed across major online booksellers and global distributor networks including Amazon, Barnes & Noble, and Ingram.\n                            </li>\n                          </ul>\n                        </div>\n\n                        <div class=\"p-3 mb-0 rounded-3\" style=\"background: #faf6f0; border-left: 4px solid #ad7d42;\">\n                          <p class=\"mb-0 editable-field\" style=\"color: #57534e; font-size: 0.88rem; line-height: 1.65;\" data-block-key=\"service.set-your-own-price.p3\" contenteditable=\"true\" spellcheck=\"false\" onblur=\"handleContentBlockSave('set-your-own-price', this)\">\n                            <em>*Consultation Note: Contact your Publishing Consultant to analyze print-on-demand base production costs and identify optimal price thresholds for your page count.</em>\n                          </p>\n                        </div>\n                      </div>\n                    </div>",
  "author-advantage-royalty-program": "<div class=\"author-advantage-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3\">The Author Advantage Royalty Program empowers you to earn substantial financial gains with every print book sold.</p>\n    <p class=\"mb-3\">This Program runs for a 3-Year Term and ensures that you receive maximum profits from sales of your book, and that you can also order copies of your own book at heavily discounted rates.</p>\n    <p class=\"mb-2\"><b>Book Pricing &amp; Royalties</b></p>\n    <p class=\"mb-3\">Figuring out how much your book will cost, and how much you will receive from each sale is easy. The retail price* will be based on your final manuscript's page count, and the royalty you receive is determined by the following calculations:</p>\n    <p class=\"mb-2\">For print copies sold on our Online Bookstore: your book’s List Price x 60% = your royalty.</p>\n    <p class=\"mb-3\">For print copies sold through channel retailers like Amazon and Barnes &amp; Noble: your book’s List Price x 15% = your royalty</p>\n    <p class=\"mb-4\">*Combining the Author Advantage Royalty Program with Set Your Own Price provides you power as the author to set a competitive retail price for your book, and to reap the maximum benefits as well. Contact your Publishing Consultant to learn more.</p>\n    <p class=\"mb-2\"><b>Start Dates for the Author Advantage Royalty Program</b></p>\n    <div class=\"mb-4\">\n      <p class=\"mb-2\">The Work (your book) will be enrolled in the Author Advantage Royalty Program on the earlier of the following:</p>\n      <p class=\"mb-2\" style=\"list-style-type: none; padding-left: 20px;\">(a) if the Work is already available for sale on the Effective Date of this Agreement, on the first day of the next calendar quarter after receipt by Company of both the signed Agreement and payment of the applicable fee for the Program;</p>\n      <p class=\"mb-2\" style=\"list-style-type: none; padding-left: 20px;\">or</p>\n      <p class=\"mb-3\" style=\"list-style-type: none; padding-left: 20px;\">(b) if the Work is not available for sale on the Effective Date of this Agreement, on the first day of the next calendar quarter after the Work becomes available, provided that Company has received payment of the Fee from the Author prior to that time.</p>\n    </div>\n    <p class=\"mb-0\"><i><strong>Please Note:</strong> To be eligible for the Author Advantage Royalty Program, your publishing package must have been purchased on or after January 2023.</i></p>\n  </div>\n</div>",
  "retail-focus": "<div class=\"retail-focus-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3\">Although self-published titles are getting more and more popular these days, self-published authors still have a difficult time getting brick-and-mortar shops to stock their books.</p>\n    <p class=\"mb-3\">Even those with great PR and marketing skills often have to go the extra mile to convince book sellers to stock their books. And unfortunately, not every author has the time or contacts needed to get this done. If your dream is to see your work displayed on a bookstore shelf, you can get the help you need with our <b>Retail Focus Service!</b></p>\n    <p class=\"mb-3\">Promote your book and let it be seen by independent bookstores with strategic print ads in two publications popular with booksellers— <b><i>Advance Catalog</i></b> and <b><i>ForeWord Magazine</i></b>—and a <b><i>customized sales kit</i></b>.</p>\n    <p class=\"mb-2\">This service includes:</p>\n    <ul class=\"mb-3\">\n      <li>Your book, pitched to <b>25 independent bookstores across the US</b> (with focus on a specific area or state) over the span of three months, using a customized sales kit</li>\n      <li>A single-slot print ad in Ingram’s <b><i>Advance Catalog</i></b></li>\n      <li>A single-slot print ad in the quarterly publication <b><i>ForeWord Magazine</i></b> (1 out of 10 slots)</li>\n      <li>The Booksellers Return Program for 12 months</li>\n      <li>A guarantee that at least 2 of the bookstores/retailers will agree to test your book</li>\n    </ul>\n    <p class=\"mb-3\">Watch the video below to learn more about how you can benefit from this service.</p>\n    <p class=\"mb-2\"><b><i>About Advance Catalog</i></b></p>\n    <p class=\"mb-3\">For over 20 years, Ingram’s <i>Advance Catalog</i> has been highlighting the best and forthcoming titles through its monthly buying guide. This publication is read by over 7,000 retailers, librarians, and international customers via print, as well as 27,000 international and domestic booksellers and librarians in digital format. Along with title listing, it also leads in editorial content, including author interviews, merchandising tips, and products news.</p>\n    <p class=\"mb-2\"><b><i>About ForeWord Magazine</i></b></p>\n    <p class=\"mb-3\">One of the most reputable publications in the industry, <i>ForeWord</i> is a bimonthly magazine with a readership of more than 30,000 librarians and booksellers— including 1,100 American Bookseller Association members—all of whom make buying decisions and reader recommendations that affect the reading habits of millions of patrons and consumers. It is carried in all Books-A-Million bookstores, select Barnes &amp; Noble stores, and independent bookstores across the US. Founded in 1998, it is still the only magazine showcasing critical reviews and title trends exclusively from the expanding independent publishing market.</p>\n    <p class=\"mb-2\"><i><strong>Important Note:</strong></i></p>\n    <ul class=\"mb-0\">\n      <li>You also have the option to extend your campaign by adding 25 more independent bookstores.</li>\n      <li>In order for us to guarantee that at least two bookstores/retailers will test your book, we may recommend that you allow our professional designers to make your book cover more acceptable to retailers at no extra cost. Retailers also prefer books that have been professionally copyedited. Make sure your book is retail-ready with these editorial services.</li>\n      <li>Your book’s official publication date must not be more than two (2) years ago; alternately, you or your book must have received recognition in any form (an award, a 5-star review, or media coverage) in the last 24 months. If your book does not meet these criteria, we cannot guarantee that the bookstores/book retailers will stock a test copy.</li>\n      <li>Your book must already be available for sale before the campaign starts.</li>\n    </ul>\n  </div>\n</div>",
  "retail-focus-for-childrens-books": "<div class=\"retail-focus-children-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3\">Children’s books have always been popular on the book market, and independent titles for children are steadily gaining popularity too. However, it can still be a challenge for self-published authors to get brick-and-mortar bookstores to stock up on their books.</p>\n    <p class=\"mb-3\">Retailers take a lot of factors into account before they stock a self-published title: things like your book’s subject and sales potential, to start with. Even authors with great PR and marketing skills often have to go the extra mile to convince book sellers to stock their books. And unfortunately, not every author has the time or contacts needed to get this done.</p>\n    <p class=\"mb-3\">If you want your book pitched to bookstores, you can get the help you need with our <b>Retail Focus for Children’s Book service!</b></p>\n    <p class=\"mb-3\">Promote your book and let it be seen by independent bookstores with strategic print ads in two publications popular with booksellers— <b><i>Advance Catalog</i></b> and <b><i>ForeWord Magazine</i></b>—and a <b>customized sales kit</b>.</p>\n    <p class=\"mb-2\">This service includes:</p>\n    <ul class=\"mb-3\">\n      <li>Your book, pitched to <b>25 independent bookstores across the US</b> (with focus on a specific area or state) over the span of three months, using a customized sales kit</li>\n      <li>A single-slot print ad in Ingram’s <b><i>Children’s Advance Catalog</i></b></li>\n      <li>A single-slot print ad in the quarterly publication <b><i>ForeWord Magazine</i></b></li>\n      <li>The Booksellers Return Program for 12 months</li>\n      <li>A guarantee that at least 2 of the bookstores/retailers will agree to test your book</li>\n    </ul>\n    <p class=\"mb-3\">Watch the video below to learn more about how you can benefit from this service.</p>\n    <p class=\"mb-2\"><b><i>About Children’s Catalog</i></b></p>\n    <p class=\"mb-3\">This is a bimonthly buying guide that highlights the best in children’s publishing. It includes children’s products for all ages, author interviews, buyer recommendations, and reviews. This publication is read by over 7,000 retailers, librarians, and international customers via print, as well as 29,000 international and domestic booksellers and librarians in digital format.</p>\n    <p class=\"mb-2\"><b>About <i>ForeWord Magazine</i></b></p>\n    <p class=\"mb-3\">One of the most reputable publications in the industry, <i>ForeWord</i> is a bimonthly magazine with a readership of more than 30,000 librarians and booksellers— including 1,100 American Bookseller Association members—all of whom make buying decisions and reader recommendations that affect the reading habits of millions of patrons and consumers. It is carried in all Books-A-Million bookstores, select Barnes &amp; Noble stores, and independent bookstores across the US. Founded in 1998, it is still the only magazine showcasing critical reviews and title trends exclusively from the expanding independent publishing market.</p>\n    <p class=\"mb-2\"><i><strong>Important Note:</strong></i></p>\n    <ul class=\"mb-0\">\n      <li>You also have the option to extend your campaign by adding 25 more independent bookstores.</li>\n      <li>In order for us to guarantee that at least two bookstores/retailers will test your book, we may recommend that you allow our professional designers to make your book cover more acceptable to retailers at no extra cost. Retailers also prefer books that have been professionally copyedited. Make sure your book is retail-ready with these editorial services.</li>\n      <li>Your book’s official publication date must not be more than two (2) years ago; alternately, you or your book must have received recognition in any form (an award, a 5-star review, or media coverage) in the last 24 months. If your book does not meet these criteria, we cannot guarantee that the bookstores/book retailers will stock a test copy.</li>\n      <li>Your book must already be available for sale before the campaign starts.</li>\n    </ul>\n  </div>\n</div>",
  "library-focus": "<div class=\"library-focus-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3\">Libraries are beloved sites of community, history, and education. They’ve always been important to readers, and they continue to be essential today, even with digital media and publishing becoming more and more part of our everyday lives. It’s only natural that authors such as yourself strive to make your work available to the community by getting libraries to stock copies of your book. Unfortunately, convincing libraries to stock self-published titles can be challenging even for the savviest authors.</p>\n    <p class=\"mb-3\">The Omni Library Focus Service helps you with your goal of making your book available in libraries through a strategic combination of print ads in two publications popular with librarians and a customized sales kit.</p>\n    <p class=\"mb-2\">The Library Focus Service includes</p>\n    <ul class=\"mb-3\">\n      <li>Your book, pitched to the Collection Development Departments and Acquisition Librarians of <b>25 public libraries across the US</b> (with focus on a specific area or state), over the span of three months, using a customized sales kit</li>\n      <li>A single-slot print ad in Baker and Taylor’s <b><i>Forecast Catalog</i></b></li>\n      <li>A single-slot print ad in the quarterly publication <b><i>ForeWord Magazine</i></b></li>\n      <li>The Booksellers Return Program for 12 months</li>\n      <li>A guarantee that at least 2 of the libraries will agree to test your book</li>\n    </ul>\n    <p class=\"mb-2\"><b>About <i>Forecast Catalog</i></b></p>\n    <p class=\"mb-3\">The most widely circulated monthly publication of Baker &amp; Taylor, Forecast Catalog boasts a subscriber base of 45,000 librarians in the US. It primarily promotes new and forthcoming adult hardcover and trade and mass-market paperback. This magazine enables publishers to reach out to libraries. By getting to know future bestsellers and other noteworthy titles, booksellers can make well-informed buying decisions. Your title information will be featured on a separate catalogue-style ad mailed with Forecast Magazine along with a select group of Author Solutions (Omni's parent company) authors.</p>\n    <p class=\"mb-2\"><b>About<i> ForeWord Magazine</i></b></p>\n    <p class=\"mb-3\">One of the most reputable publications in the industry, <i>ForeWord</i> is a bimonthly magazine with a readership of more than 30,000 librarians and booksellers— including 1,100 American Bookseller Association members—all of whom make buying decisions and reader recommendations that affect the reading habits of millions of patrons and consumers. It is carried in all Books-A-Million bookstores, select Barnes &amp; Noble stores, and independent bookstores across the US. Founded in 1998, it is still the only magazine showcasing critical reviews and title trends exclusively from the expanding independent publishing market.</p>\n    <p class=\"mb-2\"><i><strong>Important Note:</strong></i></p>\n    <ul class=\"mb-0\">\n      <li>You also have the option to extend your campaign by adding 25 more independent bookstores.</li>\n      <li>In order for us to guarantee that at least two libraries will test your book, we may recommend that you allow our professional designers to make your book cover more acceptable to libraries at no extra cost. You may also choose from these editorial services to ensure that your book has been professionally copyedited and is library-ready.</li>\n      <li>Your book’s official publication date must not be more than two (2) years ago; alternately, you or your book must have received recognition in any form (an award, a 5-star review, or media coverage) in the last 24 months. If your book does not meet these criteria, we cannot guarantee that the bookstores/book retailers will stock a test copy.</li>\n      <li>Your book must already be available for sale before the campaign starts.</li>\n    </ul>\n  </div>\n</div>",
  "booksellers-return-program": "<div class=\"booksellers-return-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3\">The ability to return unsold books is a standard publishing business practice that has remained since the Great Depression. Since that time, booksellers have been able to mitigate their own financial risk by relying on publishers to credit returned books.</p>\n    <p class=\"mb-3\">Often, booksellers will hesitate to order and stock books when they aren’t “Returnable.” This means if getting your title stocked on bookstore shelves is part of your marketing plan, Booksellers Return Program is an essential element to earning shelf space and/or in-store book signings.</p>\n    <p class=\"mb-2\"><b>When you purchase Booksellers Return Program:</b></p>\n    <ul class=\"mb-3\">\n      <li>Your book will be designated as “Returnable” in Ingram’s ipage ordering system for retailers and libraries. (Ingram is the world’s largest wholesaler and distributor of books.)*</li>\n      <li>Your book will be designated as “Returnable” in Baker &amp; Taylor’s ordering system for retailers and libraries. (Baker &amp; Taylor is a leading distributor of books, with 180 years in the business.)*</li>\n      <li>You will not be charged back for royalties earned on the sales to the store if your books are returned.</li>\n    </ul>\n    <p class=\"mb-2\"><b>What assurance can Omni give that a bookstore will order and stock my book?</b></p>\n    <p class=\"mb-3\">Omni does not have control over whether a bookstore will order and stock your book. Each bookstore, be it commercial and independently owned, manages its own business operations including which title to stock on its shelves.</p>\n    <p class=\"mb-3\">Help your title meet bookseller standards for retail stocking with Booksellers Return Program. If your book remains unsold, retailers will be able to return it without a loss of profit for them.</p>\n    <p class=\"mb-2\"><i>Please Note:</i></p>\n    <p class=\"mb-2\"><i>Your book will be designated on iPage within two to seven weeks. It can then take 30 to 60 days for returnability status to appear within individual retailers’ systems. Confirmation of your title’s listing in iPage is available upon your request.</i></p>\n    <p class=\"mb-0\"><i>* The Booksellers Return Program is valid for one year from the date your book goes live. The Booksellers Return Program Renewal is available in one year increments thereafter.</i></p>\n  </div>\n</div>",
  "booksellers-return-program-renewal": "<div class=\"booksellers-return-renewal-detail-content\">\n  <div class=\"editorial-narrative mb-4\" style=\"color: #44403c; font-size: 0.98rem; line-height: 1.75;\">\n    <p class=\"mb-3\">Renew your book’s participation in the Booksellers Return Program for one year.* When you purchase this program renewal, your book will remain “returnable” in book distributor ordering systems, ensuring bookstores that they can return any unsold copies (if they choose to stock your book).</p>\n    <p class=\"mb-2\"><b>What assurance can Omni give that a bookstore will order and stock my book?</b></p>\n    <p class=\"mb-3\">Omni does not have control over whether a bookstore will order and stock your book. Each bookstore, be it commercial and independently owned, manages its own business operations including which title to stock on its shelves.</p>\n    <p class=\"mb-0\">Renew your valuable Booksellers Return Program for one more year and help your title continue to meet bookseller standards for retail stocking. <i>*The Booksellers Return Program Renewal is valid for one year and can be renewed annually.</i></p>\n  </div>\n</div>"
  };

